const TENSION_DATA = {
  "4":  { name:"Afghanistan", level:5, summary:"Under Taliban rule since 2021, Afghanistan faces near-total political repression and a severe humanitarian crisis, now compounded by open war with Pakistan. After an Islamabad suicide bombing, Pakistan declared 'open war' on the Taliban regime and launched Operation Ghazab Lil Haq on February 26, 2026, striking over 70 targets including Bagram Airbase and Kabul; Afghanistan retaliated with cross-border attacks. The UN documented over 370 Afghan civilian deaths in the conflict's first three months alone. Ceasefires mediated by Qatar, China, and Eid-holiday truces have repeatedly collapsed, with low-intensity cross-border fighting continuing as of mid-June 2026.", reasons:["Open war with Pakistan since February 2026 (Operation Ghazab Lil Haq) — strikes on Bagram Airbase, Kabul, and border provinces","UN-documented civilian death toll exceeding 370 in the conflict's first three months, with repeated mediated ceasefires collapsing","Taliban authoritarian rule with mass human rights violations","Near-total suppression of women's rights and civil freedoms","Persistent ISIS-K insurgency and bombings","Economic collapse and humanitarian emergency","Zero international recognition of government"] },
  "8":  { name:"Albania", level:2, summary:"PM Edi Rama won a fourth consecutive term in May 2025 elections with 52.3% of the vote and 83 of 140 seats — his party's strongest result to date — running on a platform of EU membership by 2030. Despite his political dominance, concerns persist over democratic backsliding, media freedom, and organized crime infiltration of state institutions.", reasons:["Ongoing rivalry between major political parties","Organized crime influence in political and judicial spheres","EU accession process creating internal reform pressures","Democratic backsliding concerns — Rama's dominant majority reduces institutional checks on power"] },
  "12": { name:"Algeria", level:3, summary:"Algeria's military-backed government faces lingering pressure from the Hirak protest movement and internal power struggles. Regional instability in the Sahel and tensions with Morocco compound domestic challenges.", reasons:["Suppression of Hirak pro-democracy protests","Military's dominant role over civilian government","Severe diplomatic tensions with neighboring Morocco","Sahel instability spilling over borders"] },
  "24": { name:"Angola", level:2, summary:"Angola has remained relatively stable under the MPLA's long rule, though economic inequality, oil-dependency, and restricted civil liberties keep underlying tensions elevated.", reasons:["MPLA one-party dominance with limited political pluralism","High poverty and inequality despite oil wealth","Periodic crackdowns on civil society"] },
  "31": { name:"Azerbaijan", level:4, summary:"After seizing full control of Nagorno-Karabakh in 2023, Azerbaijan now faces international criticism over ethnic cleansing allegations and unresolved border disputes with Armenia.", reasons:["Seizure of Nagorno-Karabakh and mass displacement of Armenians","Unresolved border demarcation disputes with Armenia","Authoritarian governance and suppression of opposition","International human rights criticism and sanctions risk"] },
  "32": { name:"Argentina", level:2, summary:"Argentina is navigating radical economic liberalization under President Milei, with deep social divisions, currency crises, and significant popular protests against austerity measures.", reasons:["Extreme austerity measures causing social unrest","Chronic inflation and debt crisis","Sharp political polarization between Milei's bloc and left-wing opposition"] },
  "36": { name:"Australia", level:1, summary:"Australia is one of the world's most politically stable democracies. PM Anthony Albanese won a historic landslide at the May 3, 2025 federal election — Labor secured 94 seats (its highest ever tally, highest two-party-preferred vote since 1975 at 55.22%), with opposition leader Peter Dutton losing his own seat of 24 years. The result gave Labor a strong second-term majority reinforcing its centrist, climate-forward agenda. Ongoing debates around Indigenous rights, housing affordability, and China relations represent low-level tensions within a broadly stable framework.", reasons:["Debates over Indigenous recognition and treaty","Strategic tensions with China affecting trade, despite partial trade rapprochement restoring some commodity flows","Housing affordability crisis among OECD's most acute"] },
  "50": { name:"Bangladesh", level:3, summary:"The BNP, led by Tarique Rahman, swept Bangladesh's first post-Hasina parliamentary election (February 12, 2026), winning 212 of 299 seats; Rahman was sworn in as Prime Minister on February 17, 2026, ending Muhammad Yunus's 18-month interim government. The Awami League was barred from contesting, leaving Jamaat-e-Islami (77 seats) as official opposition — a historic realignment of Bangladeshi politics. The new government has pledged price stability and a $1 trillion economy by 2034, but faces high non-performing loans, fragile law and order, and a stalled Rohingya repatriation process.", reasons:["Awami League's exclusion from the 2026 election leaves deep questions about reconciliation and opposition legitimacy","Jamaat-e-Islami's rise to official opposition status raises concerns about Islamist influence on policy","Fragile law-and-order situation inherited from the 2024 uprising and interim period","Risk of social unrest if inflation and unemployment are not addressed quickly","Stalled Rohingya repatriation amid declining international aid"] },
  "56": { name:"Belgium", level:1, summary:"Belgium faces ongoing political fragmentation along linguistic and regional lines between Flemish and French-speaking communities, but manages these divisions peacefully through coalition government.", reasons:["Deep Flemish-Walloon linguistic and political divide","Chronic difficulty forming coalition governments","Rise of far-right Flemish nationalist parties"] },
  "64": { name:"Bhutan", level:1, summary:"Bhutan is a small, stable constitutional monarchy. Its main concerns are economic development and maintaining sovereignty between India and China.", reasons:["Border disputes with China in remote Himalayan territory","Economic dependency on India","Slow pace of democratic development"] },
  "68": { name:"Bolivia", level:4, summary:"Bolivia is one of South America's main centres of political instability in 2026. President Rodrigo Paz Pereira (inaugurated November 2025) faces calls to resign after just six months in office from opposition groups, MAS supporters, and civil society. Protests ignited in May 2026 over a land mortgage law amid the country's worst economic crisis in four decades; Paz annulled the law on May 13, but unrest continued and the Bolivian Workers' Central (COB), miners, teachers, and farmers staged weeks of road blockades that emptied La Paz markets and depleted hospital oxygen reserves. On May 27, 2026, Paz signed a law authorising military deployment in the streets and simplifying procedures for declaring a state of emergency, adopting the Trump administration's framing of protesters as 'narco-terrorists.' Defence Minister Marcelo Salinas resigned on June 2 (replaced by Ernesto Justiniano) and Education Minister Beatriz Garcia resigned the same week as the pressure on Paz to step down intensified. On June 9, Paz signed Law 1740, formally regulating states of emergency and authorising joint Armed Forces-police operations to suppress unrest; mass mobilisations by workers, farmers, and indigenous groups continued in La Paz and Cochabamba through June 10–11 demanding his resignation. From May 1 through early June, the unrest caused at least 10 deaths, 37 injuries, and 365 arrests, with roughly 90 road blockades maintained nationwide by unions, farmers, and indigenous groups. On June 12, El Alto protesters ambushed a police convoy, set it ablaze, and forced officers to strip off their uniforms — a sharp escalation in violence against security forces. Paz has not resigned, and the Minister of the Presidency has dismissed resignation calls as 'anti-democratic.' On June 17, Paz held the first direct talks in 48 days with Bolivian Workers' Central (COB) leader Mario Argollo at the Central Bank in La Paz; after roughly four hours the talks broke into recess with nothing signed. The COB has dropped its demand for Paz's resignation, instead pressing an eight-point list centred on the roughly 360 people detained during the unrest — the two sides formed a commission to review those cases, though the union says blockades stay shut until there is movement on releases. Road blockades have fallen only modestly, from roughly 90 at their peak to 45–49 nationwide, and access to La Paz remains difficult. The government's official cumulative toll from the unrest stands at 16 deaths and an estimated US$2.76 billion in economic losses. On June 19, Paz signed an agreement with the COB ending the union's roughly seven-week blockade campaign, but the deal did not bring nationwide calm: Paz declared a nationwide state of emergency on June 20, paving the way for military deployment, as Morales-aligned rural and peasant associations — who were not party to the COB talks — kept key roads blocked around Cochabamba.", reasons:["June 19-20, 2026: Paz signed a deal with the COB ending its blockade campaign, then declared a nationwide state of emergency the next day as Morales-aligned rural groups outside the talks kept blocking roads around Cochabamba","June 17, 2026: First talks in 48 days between Paz and COB leader Mario Argollo ended without a deal; COB dropped its resignation demand for an 8-point list focused on ~360 detainees, while blockades fell only modestly to 45–49 nationwide","Official cumulative toll from the unrest: 16 deaths and an estimated US$2.76 billion in economic losses","June 12, 2026: El Alto protesters ambushed and torched a police convoy, stripping and humiliating officers — a dangerous escalation in anti-government violence","May 27, 2026: Paz enacted law authorising military deployment in streets and easing state-of-emergency declaration, framing protesters as 'narco-terrorists' — calls for resignation after only 6 months in office","June 9, 2026: Paz signed Law 1740 formally regulating states of emergency and authorising joint Armed Forces-police operations against protesters; mass mobilisations continued in La Paz and Cochabamba June 10–11","Weeks of COB-led miner, teacher, and farmer blockades emptied La Paz markets and depleted hospital oxygen reserves","Defence Minister Marcelo Salinas resigned June 2, 2026 (replaced by Ernesto Justiniano) and Education Minister Beatriz Garcia resigned amid the deepening crisis","Radical austerity programme (30%+ spending cut) and land mortgage law generating severe social backlash","Economic crisis: worst in four decades — depleted foreign reserves, fuel shortages, persistent inflation","Deep political polarisation between new right-wing government and MAS movement","History of coups and political instability — military loyalty uncertain"] },
  "70": { name:"Bosnia and Herzegovina", level:3, summary:"Bosnia remains fractured along ethnic lines more than 25 years after the Dayton Agreement. Republika Srpska's separatist rhetoric and obstruction of state institutions poses ongoing risks.", reasons:["Republika Srpska's secessionist rhetoric from Milorad Dodik","Ethnic and political gridlock within Dayton framework","Interference from Russia and Serbia","Slow EU integration progress"] },
  "76": { name:"Brazil", level:2, summary:"Brazil experienced a serious democratic stress test with the January 8, 2023 riots. Political polarization between Lulista left and Bolsonarista right remains high, with ongoing legal battles against coup plotters.", reasons:["January 2023 coup attempt and continued polarization","Ongoing prosecution of Bolsonaro and allies","Tensions between executive and judiciary","Environmental policy disputes over Amazon"] },
  "100":{ name:"Bulgaria", level:2, summary:"Bulgaria's April 19, 2026 elections gave Rumen Radev's Progressive Bulgaria coalition a majority (~43.9%, 131/240 seats); Radev was confirmed as PM on May 8, 2026, ending years of caretaker governments. However, Radev's euroskeptic and Russia-friendly stances may complicate EU cohesion fund access and reform momentum. Endemic corruption and oligarchic networks remain deep structural challenges.", reasons:["New PM Radev's euroskeptic and Russia-friendly stance — EU cohesion fund access at risk","Endemic corruption and organized crime links to politics","Years of political gridlock have hampered EU integration progress","Pro-Russia sympathies within governing coalition creating policy tensions"] },
  "104":{ name:"Myanmar", level:5, summary:"Since the 2021 military coup, Myanmar has been engulfed in a brutal civil war. The military junta is losing territory to a broad coalition of resistance armies while committing mass atrocities against civilians.", reasons:["Military junta's violent suppression of pro-democracy movement","Multi-front civil war with ethnic armed organizations","Documented war crimes including airstrikes on civilians","Humanitarian catastrophe with millions displaced","International arms embargo and sanctions on junta"] },
  "112":{ name:"Belarus", level:4, summary:"After fraudulent 2020 elections triggered mass protests, Lukashenko violently crushed dissent with Russian backing. Belarus is now a key Russian ally, fully integrated into Moscow's orbit while its civil society is decimated.", reasons:["Authoritarian crackdown on 2020 pro-democracy protests","Full strategic alignment with Russia as proxy state","Mass imprisonment of political opponents and journalists","Economic dependency on Russia","International sanctions and diplomatic isolation from West"] },
  "116":{ name:"Cambodia", level:4, summary:"Cambodia is a de facto one-party state under the Hun family dynasty. A border military conflict with Thailand erupted in May 2025 and escalated into major fighting in July 2025, displacing over 409,000 people across northwest and western provinces. A ceasefire was declared December 27, 2025, but the truce remains fragile with continued armed incidents and mutual distrust persisting into 2026.", reasons:["Active border military conflict with Thailand (May 2025–): major escalation July 2025; 409,000+ displaced across northwest/western provinces; ceasefire (Dec 27, 2025) fragile — US Embassy security alerts for continued armed conflict in 2026","One-party Hun family rule with no meaningful opposition","Systematic suppression of civil society and free press","Land grabs and forced evictions","Deep-rooted corruption","Close strategic ties with China"] },
  "120":{ name:"Cameroon", level:4, summary:"Cameroon faces a severe Anglophone separatist crisis in its Northwest and Southwest regions, where the Ambazonia independence movement has been fighting government forces since 2016.", reasons:["Armed Anglophone separatist conflict in Northwest/Southwest","Atrocities by both military and separatist groups","Boko Haram insurgency in the Far North region","Authoritarian governance under President Biya (in power since 1982)","Humanitarian crisis with over 700,000 displaced"] },
  "124":{ name:"Canada", level:2, summary:"Canada faces an unprecedented external threat to its economic sovereignty from the United States under Trump, who has repeatedly suggested Canada should become the '51st state' and imposed sweeping tariffs. PM Mark Carney, who replaced Trudeau in early 2025, fought the election on a platform of defending Canada's sovereignty. The tariff war is causing real economic damage and reshaping the Canada-US relationship in ways unseen since WWII.", reasons:["Trump's sweeping tariffs on Canadian exports — steel, aluminium, autos hit hard","Trump's 'annexation' rhetoric challenging Canadian sovereignty","USMCA renegotiation creating deep trade uncertainty","Internal unity challenges: Quebec sovereignty sentiment, Western alienation","Indigenous reconciliation process — unmarked graves, land rights disputes","Housing affordability crisis among worst in OECD"] },
  "140":{ name:"Central African Republic", level:4, summary:"CAR remains one of the world's most fragile states. The government's reliance on Russian Africa Corps mercenaries has deepened instability and human rights abuses.", reasons:["Persistent armed group activity despite multiple peace deals","Russian Wagner/Africa Corps mercenaries operating freely","Widespread atrocities against civilians","Humanitarian catastrophe","Near-absent state authority outside Bangui"] },
  "144":{ name:"Sri Lanka", level:3, summary:"Sri Lanka experienced a catastrophic economic collapse in 2022, triggering mass protests that ousted President Rajapaksa. The country is slowly recovering but political tensions and ethnic Tamil-Sinhalese divisions persist.", reasons:["Post-2022 economic crisis and political upheaval","IMF-mandated austerity causing social hardship","Unresolved Tamil minority grievances post-civil war","Political fragility of current government"] },
  "152":{ name:"Chile", level:2, summary:"Far-right President José Antonio Kast was inaugurated on March 11, 2026 after winning the December 2025 runoff with 58.2% of the vote — Chile's first hard-right leader in the democratic era. His government is prioritising immigration crackdowns (border wall construction with Peru begun), public security, and fiscal austerity. The Mapuche conflict in Araucanía and deep polarisation between far-right and progressive-left blocs remain underlying tensions, though within democratic norms.", reasons:["Kast government (from March 2026) pursuing hard-line immigration and security measures — border wall construction begun at Peru frontier","Ongoing Mapuche land rights conflict in Araucanía — expected to intensify under Kast's security-first approach","High inequality and cost-of-living tensions","Deep polarisation: far-right Republican Party vs. progressive-left; Senate evenly divided, constraining Kast's legislative agenda"] },
  "156":{ name:"China", level:3, summary:"China is locked in an intensifying strategic rivalry with the United States. Trump's tariff war (145%+ on Chinese goods as of 2025) has escalated the trade conflict to levels not seen in decades; China has retaliated with export controls on rare earths and targeted US firms. Domestically, Xi Jinping's unprecedented third term and growing surveillance state show no signs of political liberalisation. Taiwan remains the central potential flashpoint.", reasons:["Full-scale US-China trade war — 145%+ tariffs triggering economic decoupling","Taiwan: regular PLA military exercises simulating blockade and invasion","Uyghur detention camps and cultural erasure in Xinjiang ongoing","South China Sea: aggressive enforcement of nine-dash line claims against Philippines, Vietnam","Hong Kong fully absorbed — National Security Law eliminating opposition","Xi Jinping third term: consolidation of personal power, no succession mechanism"] },
  "158":{ name:"Taiwan", level:4, summary:"Taiwan's security situation has deteriorated with the return of ambiguity around US commitment under Trump. Trump has repeatedly questioned whether the US would defend Taiwan and demanded Taiwan 'pay' for its defence. China continues regular PLA air and naval incursions into Taiwan's ADIZ. The strategic value of TSMC has made Taiwan both a prize and a leverage point in US-China competition. In response to Japan and the Philippines announcing plans (late May 2026) for maritime boundary delimitation talks, China ran a 'special maritime law enforcement operation' in waters east of Taiwan from June 1–10, 2026, deploying coast guard and survey vessels; Taiwan's coast guard dispatched ships to shadow the Chinese vessels.", reasons:["Trump's explicit questioning of US commitment to defend Taiwan — unprecedented ambiguity","Regular PLA carrier and warplane incursions into Taiwan's ADIZ","China has never renounced use of force; military modernisation targets Taiwan","TSMC's semiconductor dominance makes Taiwan a strategic flashpoint","Lack of formal international recognition limits diplomatic protection","US-China trade war escalation increases risk of miscalculation","China's June 1–10, 2026 'special maritime law enforcement operation' east of Taiwan, launched over Japan-Philippines maritime delimitation talks — Taiwan's coast guard shadowed the Chinese vessels"] },
  "170":{ name:"Colombia", level:3, summary:"Colombia continues peace negotiations with dissident FARC factions and ELN guerrillas under President Petro's 'Total Peace' policy, but ongoing violence from armed groups keeps tensions significant. On May 31, 2026, the first round of the presidential election saw far-right outsider Abelardo de la Espriella lead with 43.7% and left-wing Senator Iván Cepeda at 40.9%; a runoff is scheduled for June 21, 2026 that will determine a major ideological shift in government.", reasons:["Active ELN guerrilla operations and ceasefire violations","FARC dissident splinter groups rejecting peace deal","Pervasive drug trafficking fueling violence","Land displacement and rural conflict","Political tensions between Petro's government and opposition","May 31 first-round election: de la Espriella (R, 43.7%) vs. Cepeda (L, 40.9%); runoff June 21 — high-stakes ideological transition incoming"] },
  "178":{ name:"Republic of the Congo", level:3, summary:"Congo-Brazzaville is an authoritarian state. Political opposition is suppressed, and ethnic tensions periodically erupt into violence.", reasons:["One-party authoritarian governance","Ethnic tensions and periodic armed flare-ups","Oil wealth inequality and corruption"] },
  "180":{ name:"DR Congo", level:5, summary:"Eastern DRC has descended into one of the world's worst active conflicts. Rwanda-backed M23 rebels seized Goma (Jan 27, 2025) and Bukavu (Feb 16, 2026), capturing both major eastern cities. The US sanctioned Rwanda's army and top officials (March 3, 2026) for 'direct operational support' of M23; DRC severed diplomatic relations with Rwanda. Peace talks under the Doha process remain at impasse; hundreds of armed groups operate across the country. On May 16, 2026, the WHO declared an Ebola Bundibugyo ebolavirus outbreak in eastern DRC and Uganda a Public Health Emergency of International Concern. The outbreak has since accelerated sharply: as of June 17, DRC reported 837 confirmed cases (376 hospitalised in isolation) and 196 confirmed deaths, concentrated in Ituri province (767 cases across 20 health zones) with smaller clusters in North Kivu (67 cases, 10 health zones) and South Kivu (3 cases, 1 health zone); a burial team was attacked in Mongbwalu health zone, Ituri, and five workers were taken hostage at points of entry after false accusations of spreading Ebola. No vaccine exists for the Bundibugyo strain.", reasons:["M23/Rwanda seizure of Goma (Jan 2025) AND Bukavu (Feb 2026) — both major eastern cities lost","US sanctioned Rwandan army and senior officials (March 2026); DRC severed diplomatic ties with Rwanda","Rwanda-DRC de facto war with direct Rwandan troop involvement","Over 7 million internally displaced — world's largest IDP crisis","Hundreds of competing armed militias across vast ungoverned territory","Critical minerals (cobalt, coltan) fuelling conflict economy","WHO-declared Ebola Bundibugyo ebolavirus PHEIC (May 16, 2026) has accelerated sharply — DRC confirmed cases rose to 837 with 196 deaths by June 17, concentrated in Ituri province; a burial team was attacked and 5 workers taken hostage amid false Ebola-spreading accusations; no Bundibugyo vaccine exists"] },
  "188":{ name:"Costa Rica", level:1, summary:"Costa Rica is one of Latin America's most stable democracies, known for its lack of a standing army and strong institutions.", reasons:["Growing narco-trafficking and gang activity","Economic inequality and youth unemployment"] },
  "191":{ name:"Croatia", level:1, summary:"Croatia is an EU and NATO member with stable democratic governance. Border disputes with Bosnia and treatment of refugees draw international criticism.", reasons:["Border tensions with Bosnia and Herzegovina","Criticism over pushbacks of migrants","Occasional nationalist political rhetoric"] },
  "192":{ name:"Cuba", level:4, summary:"Cuba remains under Communist Party rule with systematic repression of dissent. Severe economic crisis and the 2021 mass protests, met with mass arrests, revealed deep popular frustration.", reasons:["One-party authoritarian Communist rule","Mass arrests of 2021 protest participants","Severe economic crisis with shortages","US economic embargo and sanctions","Mass emigration driven by desperation"] },
  "218":{ name:"Ecuador", level:3, summary:"Ecuador has been rocked by an unprecedented security crisis as drug trafficking organizations have plunged the country into gang warfare, prison massacres, and political assassinations.", reasons:["Drug cartel infiltration of state institutions","Assassinations of politicians and journalists","Prison gang massacres and chaos","State of emergency declared in multiple provinces"] },
  "231":{ name:"Ethiopia", level:4, summary:"Ethiopia's fragile post-war stability is fracturing. In April 2026, the TPLF restored the Tigray regional government, effectively ending the Pretoria peace deal signed in 2022 — reopening the risk of renewed Tigray conflict. Simultaneously, an Ethiopia-Eritrea military standoff is escalating: in February 2026 Ethiopia demanded Eritrea 'immediately withdraw' troops from its territory; military buildups along the northern border have continued into June 2026. Ethiopia's Foreign Minister Gedion Timothewos wrote to UN Secretary-General Guterres accusing Eritrea of deepening 'collusion' with the Fano and OLA insurgencies and of hosting a training camp for Sudan's RSF paramilitary group. With national elections held in June 2026, PM Abiy has increasingly framed regaining Red Sea access as a unifying national cause, further raising the stakes of the standoff. Experts warn a renewed Ethiopia-Eritrea war could involve 10–15 countries across three continents. Amhara and Oromia insurgencies continue alongside these new threats.", reasons:["TPLF restored Tigray government (April 20, 2026), breaking the Pretoria peace deal — risk of renewed Tigray war","Ethiopia-Eritrea military standoff (Feb–June 2026): Ethiopia demanded Eritrea withdraw troops; military buildups ongoing — inter-state war risk elevated","Ethiopia accused Eritrea, in a formal letter to UN chief Guterres, of collusion with Fano/OLA insurgents and hosting an RSF training camp","PM Abiy's framing of Red Sea access as a unifying cause ahead of June 2026 elections raises risk of deliberate escalation","Ongoing Amhara Fano militia insurgency after 2023 crackdown","Oromo Liberation Army (OLA-Shane) operations","Post-Tigray war trauma and unresolved grievances","Massive humanitarian crisis — millions food insecure"] },
  "232":{ name:"Eritrea", level:4, summary:"Eritrea is one of the world's most closed and repressive states with indefinite military conscription and total press suppression. In 2026, Eritrea is at the centre of a dangerous new Ethiopia-Eritrea military standoff: Ethiopia demanded an 'immediate withdrawal' of Eritrean troops in February 2026; Eritrea denied the allegations as 'fabricated.' Ethiopia has since formally accused Eritrea, in a letter to the UN Secretary-General, of colluding with Fano/OLA insurgents and hosting a training camp for Sudan's RSF. Military buildups along the shared border and the April 2026 TPLF collapse of the Pretoria peace deal dramatically elevate the risk of renewed inter-state war.", reasons:["Ethiopia-Eritrea military standoff (Feb–June 2026): Ethiopia demanded Eritrea withdraw troops; risk of renewed inter-state war elevated","Ethiopia's formal UN complaint accuses Eritrea of colluding with Fano/OLA insurgents and hosting an RSF training camp","TPLF restored Tigray government (April 2026), ending the Pretoria peace deal — risk of renewed Tigray conflict involving Eritrea","Indefinite mandatory military conscription","Zero press freedom and total political repression","Involvement in Tigray war atrocities","Extreme economic isolation"] },
  "246":{ name:"Finland", level:1, summary:"Finland joined NATO in 2023, dramatically shifting its security posture. It faces Russian hybrid warfare threats including GPS jamming and orchestrated migrant flows.", reasons:["Significant land border with hostile Russia","Russian hybrid warfare including GPS interference","Orchestrated refugee/migrant pressure at border from Russia"] },
  "250":{ name:"France", level:2, summary:"France is experiencing a prolonged political crisis. After Macron's snap election gamble in summer 2024 backfired spectacularly, the National Assembly remains hung. France has cycled through multiple prime ministers; Sébastien Lecornu has been PM since September 2025 but leads a similarly fragile minority government. The National Rally is the largest single party in parliament. France's deficit exceeds EU limits, creating budget tension.", reasons:["Hung parliament — Macron presidency weakened into lame duck status","National Rally (RN) as largest party; Le Pen well-positioned for 2027 presidential race","Fiscal deficit above 6% GDP — EU Excessive Deficit Procedure","Farmers and workers protest movements over agriculture and cost of living","Immigration and identity politics as dominant electoral fault lines","France's role in Africa collapsing — expelled from Sahel states"] },
  "262":{ name:"Djibouti", level:2, summary:"Djibouti is stable by regional standards and hosts multiple foreign military bases. It is vulnerable to regional tensions in the Horn of Africa.", reasons:["Authoritarian single-party rule","Dependence on strategic foreign military presence","Tensions from Somali and Ethiopian instability nearby"] },
  "268":{ name:"Georgia", level:4, summary:"Georgia's pro-EU government was elected in disputed 2024 elections. Mass protests erupted against the ruling Georgian Dream party's decision to suspend EU accession. Russia's occupation of 20% of its territory continues.", reasons:["Russian occupation of South Ossetia and Abkhazia","2024 disputed election results and pro-EU protest movement","Georgian Dream's autocratic drift and pro-Russian tilt","EU membership process suspended by government decision"] },
  "275":{ name:"Palestine", level:5, summary:"A comprehensive ceasefire took effect in Gaza on October 10, 2025; phase 2 (Hamas disarmament, US-supervised Palestinian administration) began January 14, 2026. Over 50,000 Palestinians were killed during the conflict; the Gaza Health Ministry reported June 18, 2026 that at least 1,005 additional Palestinians have been killed since the October 2025 ceasefire took effect. Gaza's infrastructure is in near-total ruin and reconstruction will take decades. On May 28, 2026, PM Netanyahu directed the IDF to expand its 'Yellow Line' control of Gaza from 60% to 70% of the Strip; Egyptian President Sisi publicly urged Israel at the mid-June G7 summit to abandon the plan, warning it would leave Palestinians only 30% of the territory. The West Bank faces intensified Israeli military raids and accelerating settler expansion.", reasons:["Ongoing Palestinian deaths by Israeli forces since October 2025 ceasefire — Gaza Health Ministry reported at least 1,005 killed as of June 18, 2026","Phase 2: Hamas disarmament and US-supervised governance transition — deeply uncertain outcome","Death toll exceeding 50,000 with catastrophic civilian proportion during the conflict","Near-total destruction of Gaza's housing, hospitals, and infrastructure","Netanyahu's May 28, 2026 directive to expand the 'Yellow Line' to 70% of Gaza — Sisi publicly urged Israel to abandon the plan at the G7 summit","West Bank: near-daily Israeli military raids and accelerating settler expansion","ICJ genocide case ongoing; ICC arrest warrants for Netanyahu and former Defence Minister"] },
  "276":{ name:"Germany", level:1, summary:"Germany's political situation has stabilised significantly. The February 2025 federal election delivered a clear mandate to the CDU/CSU-SPD coalition under Chancellor Friedrich Merz. The new government reformed the constitutional debt brake, unlocking a €500 billion defence and infrastructure fund. The AfD — which placed second with ~20.5% — is in opposition and subject to a formal firewall preventing coalition. Democratic institutions are functioning.", reasons:["AfD at ~20% — significant far-right voter bloc though contained in opposition","Firewall policy preventing AfD coalition may face pressure if AfD grows further","US tariff pressure on German exports creating economic headwinds","Rearmament and defence spending ramp-up — societal adjustment to new security reality"] },
  "288":{ name:"Ghana", level:2, summary:"Ghana has a strong reputation for democratic governance in West Africa. Current challenges are mainly economic, with a debt restructuring process ongoing.", reasons:["Debt restructuring and IMF program causing austerity","Economic hardship and inflation","Chieftaincy and land disputes at local level"] },
  "300":{ name:"Greece", level:2, summary:"Greece faces tensions related to migration from Turkey, territorial disputes with Turkey in the Aegean, and ongoing concerns about media freedom.", reasons:["Ongoing Aegean Sea territorial disputes with Turkey","High migration pressure at Greek-Turkish border","Wiretapping scandal affecting political trust"] },
  "320":{ name:"Guatemala", level:3, summary:"Guatemala saw a landmark democratic moment with anti-corruption President Arévalo overcoming attempts to block his inauguration. Corruption networks, gang violence, and impunity remain major challenges.", reasons:["Deep-rooted corruption and impunity","Gang violence and narco-trafficking","Attorney General's attempted obstruction of democratic transfer","High poverty and inequality"] },
  "324":{ name:"Guinea", level:3, summary:"Guinea has been under military rule since the 2021 coup. The transition to civilian rule has been delayed and political freedoms remain severely curtailed.", reasons:["Military junta rule since 2021 coup","Delayed and uncertain civilian transition","Ethnic tensions between Fulani, Malinke, and other groups"] },
  "332":{ name:"Haiti", level:5, summary:"Haiti is in a state of collapse, with gangs controlling over 80% of the capital Port-au-Prince. The government has no effective authority and a humanitarian catastrophe is unfolding.", reasons:["Gang confederation (Viv Ansanm) controlling most of Port-au-Prince","Near-total state collapse and absence of functioning government","Humanitarian catastrophe with extreme food insecurity","Assassination of President Moïse in 2021 left lasting power vacuum","Security mission struggling to make impact"] },
  "340":{ name:"Honduras", level:3, summary:"Honduras faces severe gang violence from MS-13 and Barrio 18. Corruption, impunity, and drug trafficking create systemic instability and drive mass emigration.", reasons:["MS-13 and Barrio 18 gang control of communities","Drug trafficking corridor","Endemic corruption and judicial impunity","Political tensions between government and elites"] },
  "348":{ name:"Hungary", level:2, summary:"Péter Magyar's Tisza Party won the April 12, 2026 parliamentary election in a landslide (141/199 seats), ending Orbán's 16-year rule. PM Magyar's pro-EU government is working to restore judicial independence and unblock EU cohesion funds withheld under Orbán. Tensions remain as Fidesz allies resist the transition and the deep legacy of institutional damage takes years to reverse. Hungary's EU and NATO alignment is improving markedly under the new government.", reasons:["Transition challenges: Fidesz resistance to new government and institutional rollback","Deep legacy of judicial and media capture requiring years to reverse","EU Article 7 procedure ongoing — gradual closure expected as reforms advance","Orbán loyalists holding positions in constitutional court and key state bodies","EU cohesion funds now expected to unblock — significant economic upside"] },
  "356":{ name:"India", level:3, summary:"India is the world's largest democracy but is experiencing democratic backsliding under the BJP's Hindu nationalist project. Modi won a third term in 2024 with a reduced majority. In May 2025, India launched Operation Sindoor, striking Pakistani territory after the Pahalgam terrorist attack (April 22, 26 killed); a ceasefire was agreed May 10. India suspended the Indus Waters Treaty and bilateral trade. The ceasefire is holding but relations remain frozen.", reasons:["Operation Sindoor (May 2025): India-Pakistan cross-border missile/drone strikes — ceasefire holds but relations frozen","Indus Waters Treaty suspended by India; bilateral trade, airspace, and visas also severed","Hindu nationalist policies — systematic marginalisation of Muslim minority (200M+ people)","India-China: Ladakh border standoff partially disengaged but unresolved","Democratic backsliding: press freedom, NGO crackdowns, judiciary pressure","Ethnic conflict in Manipur — state-level communal violence"] },
  "360":{ name:"Indonesia", level:2, summary:"Indonesia has transitioned power to President Prabowo. Concerns exist about democratic backsliding, Papua separatism, and inter-communal tensions.", reasons:["Papua separatist movement and military operations","Concerns about Prabowo's human rights record","Religious intolerance incidents against minorities"] },
  "364":{ name:"Iran", level:5, summary:"Iran remains in an active wartime state following Operation Epic Fury (since February 28, 2026), which killed Supreme Leader Ali Khamenei. His son Mojtaba Khamenei was elected Supreme Leader on March 8. Iran has retaliated with 500+ ballistic missiles and ~2,000 drones, striking Israel, US bases, and countries across the Middle East. Trump extended a ceasefire on April 21 at Pakistan's request, but the US Navy blockade of Iranian ports continues, keeping Iran's oil exports effectively at zero. On May 4–5, Iran struck UAE territory for the first time — 15 ballistic missiles and 4 drones hit Fujairah. The IRGC subsequently redefined the Strait of Hormuz as a 'vast operational area.' US and Iranian forces exchanged fire in the Strait around May 7 as US Navy destroyers attempted to escort merchant vessels through (US Operation Project Freedom). Trump insisted the ceasefire remains in effect. On May 23, Trump announced a deal is 'largely negotiated'; Iran's foreign ministry described it as a framework requiring 30–60-day nuclear talks. On May 24, specific deal terms were reported (Axios/CNN): a 60-day ceasefire extension during which the Strait would reopen with no tolls, Iran would sell oil freely, the US would lift its port blockade and issue sanctions waivers, and Iran would clear mines — followed by nuclear negotiations. Significant differences remain. On May 26, US Central Command struck Iranian missile launch sites and mine-laying boats in self-defense operations. On May 27, US forces struck additional Iranian military sites in southern Iran targeting threats to maritime traffic; Iran accused the US of a 'grave ceasefire violation'. On May 28, CNN reported that the US and Iran had reached a tentative agreement, though Trump had not signed off. On May 29, Trump added new demands — on Hormuz navigation, Iran's nuclear program, and frozen overseas assets — that 'didn't go down well in Tehran.' On May 30, Bloomberg reported the US insists deals with Iran for safe Hormuz transit are 'prohibited'; Iran reasserted control over the Strait. VP Vance confirmed MoU signing is 'TBD' as the two sides negotiate 'a couple of language points.' Defense Secretary Hegseth stated the US military is ready to resume combat if required. The deal remains elusive. On June 1, Iranian state media reported talks suspended over Israel's ongoing Lebanon offensive, which Tehran said 'violated' the ceasefire; Trump insisted June 2 that talks are ongoing and a deal is reachable 'over the next week.' Around June 5–6, US and Iranian forces skirmished twice in the Strait of Hormuz even as framework talks continued. On June 6, the US shot down Iranian drones and struck Iranian radar sites. On June 7–8, ceasefire negotiations faltered as Israel and Iran traded the worst mutual strikes in months; Iran launched a major missile attack on Israel (June 8), prompting Trump to urgently warn Netanyahu against further escalation. On June 9, Iran launched retaliatory strikes on US military bases in Bahrain and Jordan; Kuwait's air defences intercepted an Iranian attack. On June 10, US forces struck Iranian military targets in Jask, Qeshm, and Bandar Abbas. On June 11, US forces fired 49 Tomahawk missiles at Iranian targets; Iran's joint military command declared a complete closure of the Strait of Hormuz including to all oil tankers and commercial ships — the most severe closure since the war began. Trump threatened to seize Kharg Island (handling ~90% of Iran's oil exports) and 'other oil infrastructure points', before later cancelling further strikes citing discussions with Iran. On June 12, the IAEA declared Iran in breach of its non-proliferation obligations; UN Secretary-General Guterres warned of the risk of return to 'full war'; draft ceasefire extension proposals are being exchanged via Qatar mediation. On June 13, Pakistan's PM Shehbaz Sharif announced that the US and Iran have agreed on the 'final' wording of a peace deal — the first significant breakthrough toward ending the conflict and reopening the Strait of Hormuz. On June 14, the US and Iran formally announced a ceasefire deal — the Islamabad Memorandum, to be signed June 19 at Bürgenstock, Switzerland — including immediate cessation of hostilities on all fronts (including Lebanon), toll-free Strait of Hormuz navigation, Iran's indefinite nuclear weapons prohibition, and lifting of the US naval blockade; oil prices fell to ~$83/barrel on the announcement. On June 15, Trump and VP Vance digitally signed the MoU at the White House — with Iranian Parliament Speaker Mohammad Bagher Ghalibaf signing for Iran — ahead of the in-person ceremony in Switzerland; the text has not been made public. On June 16, FM Araghchi warned that any Israeli attack on Lebanon or continued occupation of Lebanese territory would be deemed a violation of the MoU, while Israel said its forces would not withdraw from areas seized in Lebanon, Syria, and Gaza, casting doubt on whether the Lebanon front is actually covered. On June 17, ship-tracking data showed the first Iranian crude tankers since the blockade began — NITC supertankers Diona and Hero 2 plus a third vessel, carrying a combined ~4.8 million barrels — exit the Strait of Hormuz, an early concrete sign of de-escalation two days ahead of the planned signing, even as the Lebanon dispute and 60-day nuclear talks remain unresolved. On June 18–19, the planned Bürgenstock implementation talks collapsed before they began: Pakistan's PM Sharif called off his trip once it was clear the MoU had already been finalised electronically (June 15) and in person at Versailles (June 17), US VP Vance postponed his own travel citing unresolved logistics, and Iran's own negotiating delegation suspended its departure in protest at continued Israeli strikes in southern Lebanon — leaving implementation talks without a new date. Strait of Hormuz traffic remains far from normal: commercial transits are running at roughly 5–10% of pre-war levels (fewer than 10 vessels daily versus 100+ before the closure), held back by unresolved mine-clearance and war-risk insurance issues; Kpler estimates a recovery to ~40 transits/day (about half of prewar volume) within 30 days if implementation talks hold. Brent crude eased further to ~$78/barrel by June 18. On June 18, Supreme Leader Mojtaba Khamenei said he had authorised the MoU despite holding a 'different view,' citing assurances from President Pezeshkian on safeguarding Iran's rights and the 'Resistance Front'; the same day, the deal's $300 billion Iran reconstruction fund provision — envisioned as a Gulf/Asia-financed private vehicle rather than direct US funding — became a Washington political flashpoint after Trump called reports of US funding 'fake news' and VP Vance said the US 'isn't giving up a cent.' Separately, three Saudi-flagged tankers (Shaden, Jaham, plus a third) carrying ~6 million barrels crossed the Strait on June 18, the first Saudi-owned crossings since the war began. On June 19, the Lebanon front flared again — a Hezbollah attack killed 4 Israeli soldiers and Israeli retaliatory strikes on 80+ targets killed at least 83 people and wounded 141, per the Lebanese Health Ministry's final toll, in Lebanon's second-deadliest day of the war — underscoring Araghchi's June 16 warning that continued fighting in Lebanon would violate the MoU, before the US and Qatar brokered a renewed Israel-Hezbollah ceasefire effective 4pm. That truce proved short-lived: on June 20, Hezbollah fired 50+ projectiles overnight at IDF positions in southern Lebanon, and Israeli retaliatory strikes on Nabatiyeh-area villages killed at least 32 people, including 2 children, again threatening the wider Islamabad Memorandum just as Hormuz shipping showed tentative recovery — JMIC/UKMTO downgraded the regional maritime threat level to 'substantial' from 'severe' on June 17, and at least 25 vessels (~20 tankers, ~10 million barrels) transited the Strait on June 18, the busiest day in weeks, though Friday June 19 traffic slowed again and Brent crude steadied near $80/barrel amid the still-unscheduled Bürgenstock implementation talks. That uptick proved short-lived: hours later on June 20, Iran's Khatam al-Anbiya Central Headquarters announced the Strait of Hormuz was being closed again to commercial traffic, framing it as a first-step response to the US and Israel's breach of the MoU's first clause over the Lebanon strikes and warning of further measures if 'the enemy' does not comply. In an apparent split within Tehran, Iran's own Foreign Ministry told Tasnim that shipping was 'operating normally' and denied any closure, while US VP Vance also publicly disputed that Iran had closed the Strait on Fox News — even as Iran's negotiating delegation was reported heading to Switzerland for talks, leaving it unclear whether the closure announcement, the denials, or the continuing diplomacy best reflects Tehran's actual position. US Central Command publicly rebutted Iran's closure claim on June 21, reporting that 55 merchant ships carrying more than 17 million barrels of oil transited the Strait on June 20 alone; the same day, Trump threatened to impose US tolls on Hormuz transit — framed as payment for America's 'Guardian Angel' role in the Middle East — if a final deal is not reached within the 60-day ceasefire window. Later on June 21, the Bürgenstock implementation talks — collapsed two days earlier — formally got underway at the Lake Lucerne hotel complex, with VP Vance leading the US delegation, Iranian Parliament Speaker Ghalibaf leading Tehran's, and Pakistan and Qatar mediating; Vance told reporters the priority was progress on the nuclear issue and the Lebanon ceasefire, launching the 60-day sprint on technical details.", reasons:["June 21, 2026: The Bürgenstock implementation talks formally launched at Lake Lucerne after their June 19 collapse, with VP Vance leading the US delegation and Speaker Ghalibaf leading Iran's, Pakistan and Qatar mediating — Vance named the nuclear issue and the Lebanon ceasefire as the two priorities for the 60-day technical sprint","June 20, 2026: Iran's Khatam al-Anbiya Central Headquarters announced a fresh closure of the Strait of Hormuz over Israel's Lebanon strikes, but Iran's own Foreign Ministry denied it and US VP Vance disputed the claim, even as Iran's delegation was reported still heading to Switzerland for talks","June 20, 2026: Renewed ceasefire broken within a day — Hezbollah fired 50+ projectiles overnight; Israeli strikes killed at least 32, including 2 children — while Hormuz traffic ticks up (25 vessels June 18, threat level cut to 'substantial') but remains far below prewar levels","June 21, 2026: US CENTCOM rebutted Iran's Hormuz closure claim, reporting 55 merchant ships carrying 17M+ barrels transited the Strait on June 20; Trump threatened US tolls on Hormuz transit if a final deal is not reached within the 60-day ceasefire window",
    "June 19, 2026: Renewed Hezbollah-Israel fighting in Lebanon (4 Israeli soldiers killed; Israeli strikes killed at least 83 and wounded 141 in Lebanon, per the Lebanese Health Ministry's final toll, the war's second-deadliest day) reignited the dispute over the MoU's Lebanon coverage before a US/Qatar-brokered ceasefire took effect","Active war with US and Israel; US-Iran exchange of fire in Strait (~May 7) after IRGC redefined it as 'vast operational area'","First-ever Iranian ballistic missile attack on UAE territory (May 4–5, 2026) — conflict expanding geographically","Strait of Hormuz effectively closed; US Operation Project Freedom (May 4) failed to restore commercial shipping","Mojtaba Khamenei — IRGC-aligned hardliner — elected Supreme Leader March 8, 2026","Iran's oil exports effectively zero; economy contracting sharply (IMF: -6.1% in 2026)","May 24–30: CNN (May 28) tentative agreement; May 29 Trump added new demands (Hormuz, nuclear, frozen assets) rejected by Tehran; May 30 Bloomberg: US insists Hormuz transit deals 'prohibited'; Iran reasserts Hormuz control; VP Vance: MoU signing 'TBD'; deal remains elusive; Hegseth warns US military ready to resume combat; May 26–27 US struck Iranian sites; Iran accused US of 'grave ceasefire violation'; June 1: Iran suspended talks over Israel's Lebanon offensive (Tehran: Israel 'violated' ceasefire); Trump June 2 insists talks continue, deal reachable 'over next week'; early June 2026: Trump submitted revised terms demanding firmer written commitments on uranium enrichment and disposal; Iran reviewing updated framework; ~June 5–6: US-Iran forces skirmished twice in the Strait; June 6: US shot down Iranian drones and struck radar sites; June 7–8: Israel-Iran worst mutual strikes in months; Iran major missile strike on Israel, Trump urged Netanyahu restraint/warned of isolation; June 9: Iran struck US military bases in Bahrain and Jordan; Kuwait intercepted Iranian attack; June 10: US struck Iranian military targets at Jask, Qeshm, and Bandar Abbas; June 11: US fired 49 Tomahawk missiles at Iranian targets; Iran declared complete Strait of Hormuz closure including to all oil tankers and commercial ships (most severe yet); Trump threatened to seize Kharg Island (~90% of Iran's oil exports) and 'other oil infrastructure points', later cancelled further strikes citing Iran discussions; June 12: IAEA declared Iran in breach of non-proliferation obligations; UN SG Guterres warned of full war risk; Qatar-mediated ceasefire extension talks underway","June 14, 2026: US and Iran formally announced ceasefire deal — signing June 19 in Switzerland; includes cessation of hostilities on all fronts (including Lebanon), toll-free Hormuz navigation, Iran's indefinite nuclear weapons prohibition, US lifting naval blockade; Brent crude fell to ~$83/barrel","June 15–16, 2026: Trump and Vance digitally signed the MoU (Iran's Ghalibaf signing for Tehran) ahead of the June 19 Switzerland ceremony; Araghchi then warned any Israeli attack on Lebanon or continued occupation would violate the MoU, while Israel said its forces will stay in seized Lebanese, Syrian, and Gaza territory — a major dispute over the deal's actual scope","June 17, 2026: First Iranian oil tankers (NITC's Diona and Hero 2, plus a third vessel) exited the Strait of Hormuz since the US blockade began — ~4.8 million barrels of crude — signalling the blockade is unwinding two days before the planned June 19 signing, though the Lebanon dispute remains unresolved","June 18–19, 2026: The planned Bürgenstock implementation talks collapsed before they began — Pakistan's PM Sharif, US VP Vance, and Iran's own delegation all pulled out, the latter citing continued Israeli strikes in Lebanon — leaving implementation talks without a new date; commercial Hormuz traffic remains at just 5–10% of pre-war levels with full recovery weeks away; Brent crude eased to ~$78/barrel","June 18, 2026: Supreme Leader Mojtaba Khamenei said he approved the MoU despite a 'different view'; the deal's $300 billion Iran reconstruction fund — a Gulf/Asia-financed private vehicle, not direct US funding — became a Washington political flashpoint after Trump called reports of US funding 'fake news' and VP Vance said the US 'isn't giving up a cent'; separately, three Saudi-flagged tankers (Shaden, Jaham, plus a third) crossed Hormuz carrying ~6 million barrels, the first Saudi-owned crossings since the war began"] },
  "368":{ name:"Iraq", level:4, summary:"Iraq has been drawn into the US-Israel-Iran war: Iranian missiles and drones have struck US military bases on Iraqi soil, and Iran-backed militias within Iraq are actively fighting US forces. After a five-month political deadlock, a new government formed: Kurdish politician Nizar Amidi was elected president (April 11, 2026) and Ali al-Zaidi — a 40-year-old banker backed by the Shia Coordination Framework — was confirmed PM by parliament on May 14, 2026 with a partial cabinet. The new government, still structurally aligned with Iran, has called for US withdrawal but lacks leverage to enforce it.", reasons:["US military bases in Iraq struck by Iranian retaliation missiles and drones (active war)","Iran-backed militias within Iraq joining Iranian campaign against US forces","New PM Ali al-Zaidi (confirmed May 14, 2026) backed by Shia Coordination Framework — Iran-aligned structural alignment continues","Political system captured by sectarian and militia interests; al-Zaidi cabinet only partially formed","Kurdish regional tensions over oil revenue and autonomy","Strait of Hormuz closure disrupting Iraqi oil export revenues"] },
  "376":{ name:"Israel", level:5, summary:"A comprehensive Gaza ceasefire took effect October 10, 2025; phase 2 (Hamas disarmament, governance transition) began January 14, 2026. On February 28, 2026, US and Israeli forces struck Tehran, killing Supreme Leader Ali Khamenei (Operation Epic Fury). Iran has retaliated directly against Israel with 90+ missile and drone strikes. A 2026 Lebanon war has also broken out. The conflict is now a multi-front active war. ICC arrest warrants for PM Netanyahu remain outstanding. On May 28, Netanyahu directed the IDF to expand its Gaza 'Yellow Line' control from 60% to 70% of the Strip; Egyptian President Sisi publicly called on Israel to abandon the plan at the mid-June G7 summit, warning it would leave Palestinians only 30% of Gaza. On June 7–8, Israel and Iran traded the worst mutual strikes in months; Iran launched a major missile attack on Israel on June 8, and Trump intervened to warn Netanyahu that further escalation risked isolating Israel. Despite the June 14 announcement of a US-Iran ceasefire deal covering Lebanon, Hezbollah drones struck northern Israel hours later and the IDF retaliated by striking a Hezbollah command centre in Beirut's Dahiyeh district; Iran vowed the strike would 'not go unanswered,' raising fresh doubt over whether the Lebanon front will hold ahead of the deal's planned June 19 signing. On June 15, Trump and Vance digitally signed the MoU with Iran (Ghalibaf signing for Tehran) ahead of the June 19 Switzerland ceremony. On June 16, PM Netanyahu said the IDF would not withdraw from areas seized in Lebanon, Syria, and Gaza, and far-right security minister Ben-Gvir declared 'Trump's agreement does not bind us' — directly contradicting Iran's claim that continued occupation would violate the deal. On June 17, the IDF attempted to capture the Ali al-Taher hill near Nabatieh in southern Lebanon; Hezbollah claimed to have repelled the assault in fierce fighting, even as Trump signed the US-Iran MoU in person at Versailles that same day — underscoring that active combat continues on the Lebanon front despite the diplomatic breakthrough. The planned June 19 Bürgenstock implementation talks subsequently collapsed before they began, as Pakistan's PM Sharif, US VP Vance, and Iran's own delegation all withdrew — the latter citing continued Israeli strikes in Lebanon — leaving the dispute over the Lebanon front's status within the MoU unresolved. Hours later that same day, Hezbollah killed 4 Israeli soldiers in a cross-border attack; the IDF retaliated by striking 80+ targets across Lebanon, killing at least 83 and wounding 141, per the Lebanese Health Ministry's final toll — the war's second-deadliest day since fighting flared in March — before the US and Qatar brokered a renewed ceasefire effective 4pm; the IDF said it remains ready to resume fighting and will keep its forces in southern Lebanon. The truce held barely a day: on June 20, Hezbollah fired 50+ projectiles overnight at IDF positions in the south, prompting Israeli strikes that killed at least 32 people, including 2 children — a fresh reminder that the Lebanon front remains the weak point of the broader US-Iran ceasefire framework. Iran's military responded by announcing a fresh closure of the Strait of Hormuz to commercial traffic, blaming the Lebanon strikes for breaching the MoU, though Iran's own Foreign Ministry denied any closure was in effect and US VP Vance publicly disputed the claim — a split that, combined with Iran's negotiating team reportedly still heading to Switzerland for talks, leaves the Lebanon front's effect on the wider ceasefire deeply ambiguous. On June 21, US CENTCOM publicly rebutted Iran's closure claim, reporting that 55 merchant ships carrying more than 17 million barrels of oil transited the Strait on June 20 alone, and Trump threatened US tolls on Hormuz transit — framed as payment for America's 'Guardian Angel' role in the Middle East — if a final deal is not reached within the 60-day ceasefire window. Later on June 21, the Bürgenstock implementation talks — collapsed two days earlier — formally got underway at the Lake Lucerne hotel complex, with VP Vance leading the US delegation, Iranian Parliament Speaker Ghalibaf leading Tehran's, and Pakistan and Qatar mediating; Vance told reporters the priority was progress on the nuclear issue and the Lebanon ceasefire, launching the 60-day sprint on technical details.", reasons:["June 21, 2026: The Bürgenstock implementation talks formally launched at Lake Lucerne after their June 19 collapse, with VP Vance leading the US delegation and Speaker Ghalibaf leading Iran's, Pakistan and Qatar mediating — Vance named the nuclear issue and the Lebanon ceasefire as the two priorities for the 60-day technical sprint","June 20, 2026: Iran's military announced a Hormuz closure in retaliation for Israel's Lebanon strikes, but Iran's Foreign Ministry denied it and US VP Vance disputed the claim, even as Iran's delegation was reported still heading to Switzerland for talks","June 20, 2026: Ceasefire broken again within a day — Hezbollah fired 50+ projectiles overnight at IDF positions; Israeli retaliatory strikes killed at least 32, including 2 children","June 21, 2026: US CENTCOM rebutted Iran's Hormuz closure claim, reporting 55 merchant ships carrying 17M+ barrels transited the Strait on June 20; Trump threatened US tolls on Hormuz transit if a final deal is not reached within the 60-day ceasefire window",
    "June 19, 2026: Hezbollah killed 4 Israeli soldiers; IDF retaliated with strikes on 80+ Lebanese targets, killing at least 83 and wounding 141, per the Lebanese Health Ministry's final toll — the war's second-deadliest day — before a US/Qatar-brokered ceasefire took effect; IDF says it will remain in southern Lebanon and is ready to resume fighting if called upon","Active war with Iran — Iran has struck Israel with 90+ missile/drone attacks since Feb 28, 2026; June 7–8: worst mutual strikes in months; Iran major missile attack June 8; Trump warned Netanyahu against further escalation","June 17, 2026: IDF assault on Ali al-Taher hill near Nabatieh repelled by Hezbollah amid fierce fighting — Lebanon front remains active despite the US-Iran ceasefire framework","June 14, 2026: Hezbollah drones struck northern Israel hours after the US-Iran ceasefire announcement; IDF struck a Hezbollah command centre in Beirut's Dahiyeh district in response; Iran vowed retaliation","June 16, 2026: Netanyahu said the IDF will not withdraw from seized territory in Lebanon, Syria, and Gaza; Ben-Gvir said 'Trump's agreement does not bind us' — opposition accused Netanyahu of an 'absolute failure'; directly clashes with Iran's claim that continued occupation breaches the MoU","2026 Lebanon war — Hezbollah re-escalating alongside Iranian retaliation","Operation Epic Fury (Feb 28): US-Israeli strike killed Supreme Leader Khamenei — Iran vows to fight on","Gaza ceasefire phase 2 (Jan 2026) — Hamas disarmament and governance transition deeply uncertain","Netanyahu's May 28, 2026 directive to expand IDF 'Yellow Line' control to 70% of Gaza — publicly opposed by Egypt's Sisi at the G7 summit","ICC arrest warrant for PM Netanyahu (international travel restricted)","West Bank: systematic military raids and accelerated settlement expansion"] },
  "380":{ name:"Italy", level:2, summary:"Italy under PM Giorgia Meloni has maintained EU and NATO commitments despite far-right roots. Political instability, organized crime, and migration tensions remain ongoing concerns.", reasons:["Coalition government fragility","Mafia and organized crime influence","Mediterranean migration pressure and EU policy disputes","Economic north-south divide"] },
  "384":{ name:"Ivory Coast", level:2, summary:"Ivory Coast has emerged from past civil wars as a relatively stable regional power. However, political tensions and Sahel spillover remain concerns.", reasons:["Political tensions around presidential term limits","Sahel instability and jihadist spillover from Mali/Burkina Faso","Lingering post-civil war ethnic divisions"] },
  "392":{ name:"Japan", level:3, summary:"Japan's first female PM, Sanae Takaichi, took office in October 2025 and called a snap election on February 8, 2026, winning a historic LDP supermajority — 316 seats (the most any party has won in the postwar lower house), enough on its own to propose constitutional amendments. The 2025–2026 China–Japan diplomatic crisis has escalated significantly: China constructed a new structure in the East China Sea despite protests; four armed Chinese coastguard ships entered Japanese territorial waters in April 2026; PLA warships transited Japanese territorial and contiguous waters prompting China's Eastern Theater Command to launch combat-readiness patrols in the East China Sea; and Chinese and Japanese coastguard ships have clashed near the disputed Diaoyu/Senkaku Islands. Analysts at Foreign Policy warned (April 28, 2026) that a Japan-China military clash has become 'dangerously likely'. In late May 2026, Japan and the Philippines announced plans to begin formal talks delimiting their maritime EEZ/continental-shelf boundary during President Marcos Jr.'s visit to Tokyo; China responded with a 'special maritime law enforcement operation' east of Taiwan (June 1–10) and accused the two countries of violating its maritime rights under UNCLOS. North Korean ballistic missile tests remain a parallel threat.", reasons:["2025–2026 China–Japan diplomatic crisis: four armed Chinese ships in Japanese territorial waters, PLA Eastern Theater Command combat-readiness patrols, fresh coastguard confrontations near Diaoyu/Senkaku Islands","China building new structure in East China Sea despite protests; analysts warn a military clash is 'dangerously likely' (Foreign Policy, April 28, 2026)","Japan-Philippines maritime delimitation talks (announced late May 2026) triggered a Chinese 'special law enforcement operation' near Taiwan and accusations of UNCLOS violations — widening the regional flashpoint","LDP supermajority (Feb 8, 2026 snap election, 316 seats) now enables constitutional revision — pacifist Article 9 amendment under active debate","North Korean ballistic missile tests over Japanese territory","Rising defence spending — Takaichi's strengthened mandate accelerating push well beyond 2% of GDP target"] },
  "398":{ name:"Kazakhstan", level:2, summary:"Kazakhstan suppressed major protests in January 2022 with Russian CSTO assistance. President Tokayev has moved to distance himself from Russia while navigating carefully between Moscow and the West.", reasons:["Authoritarian governance with suppressed political opposition","Balancing act between Russia, China, and Western interests","Economic dependence on Russia while seeking diversification","Suppressed January 2022 uprising left unresolved grievances"] },
  "400":{ name:"Jordan", level:4, summary:"Jordan is under mounting pressure from the Gaza war next door, a massive refugee burden, and economic difficulties. On June 9, 2026, Iran launched retaliatory strikes on US military bases in Jordan, directly drawing the country into the US-Iran war and dramatically raising its security risk profile. On June 11, the Jordanian military intercepted 20 Iranian missiles targeting an area hosting a US military base.", reasons:["Iran struck US military bases in Jordan (June 9, 2026) — Jordan drawn directly into the US-Iran war","June 11, 2026: Jordanian military intercepted 20 Iranian missiles targeting US military base — ongoing direct threat","Gaza war spillover — economic and political pressure","Hosting world's highest per-capita refugee population","Economic stress and youth unemployment","Balancing Israel relations vs. Palestinian solidarity"] },
  "404":{ name:"Kenya", level:2, summary:"Kenya saw significant anti-government protests in 2024 driven by youth frustration over taxation and corruption. The government responded with both crackdowns and concessions.", reasons:["2024 youth-led protests against Finance Bill and corruption","Ethnic-based political competition and patronage","Security challenges from Al-Shabaab in northeast","Economic stress and high cost of living"] },
  "408":{ name:"North Korea", level:4, summary:"North Korea has deployed tens of thousands of troops to fight alongside Russia in Ukraine, marking a dangerous expansion of its international military role. In exchange, North Korea has reportedly received advanced weapons technology and satellite assistance from Russia. The nuclear program continues to advance.", reasons:["10,000–15,000+ troops deployed to Russia for Ukraine war — unprecedented move","Advanced nuclear arsenal with ICBMs capable of reaching US mainland","Declared South Korea a 'hostile state' — abandonment of reunification goal","Russia-DPRK military-technology exchange deepening","Chronic famine and food insecurity despite military-first spending"] },
  "410":{ name:"South Korea", level:2, summary:"South Korea navigated its worst political crisis in decades after President Yoon Suk-yeol's December 2024 martial law declaration and subsequent impeachment. Progressive opposition leader Lee Jae-myung won the June 2025 presidential election, restoring democratic normalcy — but the country remains deeply polarized. North Korea's troop deployments to Russia have elevated the military threat perception.", reasons:["Post-Yoon constitutional crisis — deep conservative-progressive polarization remains","North Korea's troop deployment to Russia and declared hostility raising threat level","Lee Jae-myung's presidency faces strong conservative opposition bloc","Trump alliance uncertainty — US troop presence and extended deterrence questioned","South Korea's export economy vulnerable to US-China tariff war","Gender polarization (young men vs. women) one of highest in any democracy"] },
  "414":{ name:"Kuwait", level:4, summary:"Kuwait was directly attacked by Iran on June 3, 2026 — 30 ballistic missiles and drones struck Kuwait International Airport, killing 1 (an Indian national) and injuring 63, severely damaging airport facilities and freezing all airport activity. Kuwait's military intercepted 13 missiles and 17 drones. The attack marked a dramatic escalation of the US-Iran war onto Kuwaiti soil. Underlying the security emergency is Kuwait's chronic political deadlock between the elected parliament and the ruling Al-Sabah family. On June 11, Kuwait again activated air defenses as Iran launched fresh missile strikes following renewed US bombardment of Iranian targets.", reasons:["Iran directly struck Kuwait International Airport (June 3, 2026) — 1 killed, 63 injured; 30 ballistic missiles and drones launched; airport severely damaged and frozen","Kuwait's air defences intercepted 13 missiles and 17 drones — first direct wartime attack on Kuwait since 1991","Drawn into US-Iran regional war as an involuntary target — US military installations in Kuwait a likely trigger","June 9, 2026: Kuwait air defences intercepted another Iranian attack — ongoing direct threat to Kuwait from Iran","June 11, 2026: Kuwait air defences activated again against additional Iranian missile strikes following new US strikes on Iran","Chronic executive-legislative gridlock between parliament and Al-Sabah family","Succession concerns within Al-Sabah ruling family"] },
  "417":{ name:"Kyrgyzstan", level:3, summary:"Kyrgyzstan has a history of revolutions and political upheaval. Under President Japarov, democratic norms are eroding, and border clashes with Tajikistan have shown the risk of inter-state conflict.", reasons:["Authoritarian consolidation under Japarov","Border conflict with Tajikistan over water and land","Russian influence and CSTO membership","History of coups and political instability"] },
  "418":{ name:"Laos", level:2, summary:"Laos is a one-party communist state that maintains stability through repression. Its growing economic and political dependency on China raises sovereignty concerns.", reasons:["Single-party LPRP rule with no political opposition","Deepening debt-trap dependency on China","Forced disappearances of civil society activists"] },
  "422":{ name:"Lebanon", level:4, summary:"Lebanon was drawn into active war as Hezbollah re-escalated alongside Iran's 2026 retaliatory campaign against Israel. On June 1, Israel and Hezbollah agreed to a preliminary ceasefire under a US proposal — Israel committed not to target Beirut's southern suburbs and Hezbollah vowed not to attack Israel — but continued cross-border attacks put it immediately under threat. Israel and the Lebanese government then reached a broader ceasefire agreement in Washington on June 3, 2026 — but Hezbollah immediately and publicly rejected it, calling the deal 'absurd, humiliating and insulting.' Hezbollah leader Naim Kassem pledged to continue fighting as long as Israeli forces remain in southern Lebanon; Israeli strikes killed 4 in Lebanon on June 4. A fifth round of direct Israel-Lebanon talks (political and military tracks, excluding Hezbollah) is now confirmed for Washington, DC on June 23-25, announced by the US State Department after a June 19 call between Secretary of State Rubio and President Aoun. The April 16 ceasefire and its 45-day extension have effectively collapsed. Israel launched new strikes May 18 including a Baalbek airstrike that killed an Islamic Jihad commander. The fragile political gains of early 2025 — a new president, a reform government — remain under severe strain. The US-Iran ceasefire deal announced June 14 explicitly includes Lebanon in the cessation of hostilities, but hours after the announcement, Hezbollah drones struck northern Israel and Israel retaliated by striking a Hezbollah command centre in Beirut's Dahiyeh district; Iran vowed the strike would 'not go unanswered.' This flare-up, just days before the deal's planned June 19 signing in Switzerland, casts doubt on whether the Lebanon front will actually fall silent. On June 14, Israel also issued forced displacement orders for 29 towns across southern Lebanon and struck Beirut's southern suburbs, killing at least 3 — a dramatic widening of the front even as the wider regional ceasefire was being announced. On June 16, Iran's FM Araghchi declared that any further Israeli attack on Lebanon, or continued occupation of seized Lebanese territory, would be treated as a violation of the US-Iran MoU; Israel rejected this framing, with PM Netanyahu confirming IDF forces will remain in areas seized in Lebanon and security minister Ben-Gvir stating 'Trump's agreement does not bind us' — leaving Lebanon's fate within the ceasefire deeply contested just days before the planned June 19 signing. On June 17, the IDF attempted to seize the strategic Ali al-Taher hill southeast of Nabatieh; Hezbollah claimed to have repelled the assault in fierce combat, even as Trump and Iran's Pezeshkian signed the MoU the same day at Versailles — concrete evidence that fighting on the ground has not stopped despite the diplomatic momentum. The planned June 19 Bürgenstock implementation talks collapsed before they began — Pakistan's PM Sharif called off his trip, US VP Vance postponed his own travel citing unresolved logistics, and Iran's delegation suspended its departure in protest at continued Israeli strikes in Lebanon — leaving Lebanon's unresolved status within the deal unaddressed, with the now-confirmed June 23-25 Washington Israel-Lebanon talks the key near-term test of whether the front actually goes quiet. Hours later, on June 19, Hezbollah killed 4 Israeli soldiers in a cross-border attack; the IDF retaliated by striking more than 80 targets across Lebanon, killing at least 83 people and wounding 141, per the Lebanese Health Ministry's final toll — the war's second-deadliest day since fighting flared in March — before the US and Qatar brokered a renewed ceasefire effective 4pm local time; the IDF confirmed the truce but said it remains ready to resume fighting and will keep its forces in southern Lebanon. The renewed truce lasted barely a day: on June 20, Hezbollah fired more than 50 projectiles overnight at IDF positions in the south, and Israel responded with strikes across the Nabatiyeh area that killed at least 32 people over the course of the day, including 2 children. The fighting again calls into question whether the Lebanon front can be reconciled with the broader Islamabad Memorandum, with implementation talks still unscheduled. In direct response, Iran's Khatam al-Anbiya Central Headquarters announced it was closing the Strait of Hormuz to commercial traffic, casting the Lebanon strikes as a US-Israeli breach of the MoU's first clause — though Iran's own Foreign Ministry denied any closure and US VP Vance disputed it, while Iran's delegation was reported still heading to Switzerland for talks, underscoring how directly the Lebanon front's fate is now entangled with the wider ceasefire's credibility. On June 21, US CENTCOM rebutted Iran's closure claim, reporting that 55 merchant ships carrying more than 17 million barrels of oil transited the Strait on June 20 alone, and Trump threatened US tolls on Hormuz transit — framed as payment for America's 'Guardian Angel' role in the Middle East — if a final deal is not reached within the 60-day ceasefire window. Later on June 21, the Bürgenstock implementation talks — collapsed two days earlier — formally got underway at the Lake Lucerne hotel complex, with VP Vance leading the US delegation, Iranian Parliament Speaker Ghalibaf leading Tehran's, and Pakistan and Qatar mediating; Vance told reporters the priority was progress on the nuclear issue and the Lebanon ceasefire, launching the 60-day sprint on technical details.", reasons:["June 21, 2026: The Bürgenstock implementation talks formally launched at Lake Lucerne after their June 19 collapse, with VP Vance leading the US delegation and Speaker Ghalibaf leading Iran's, Pakistan and Qatar mediating — Vance named the nuclear issue and the Lebanon ceasefire as the two priorities for the 60-day technical sprint","June 20, 2026: Iran announced a Hormuz closure explicitly citing Israel's Lebanon strikes, though Iran's Foreign Ministry denied it and US VP Vance disputed the claim, even as Iran's delegation was reported still heading to Switzerland for talks","June 20, 2026: Renewed ceasefire broken within a day — Hezbollah fired 50+ projectiles overnight; Israeli strikes across the Nabatiyeh area killed at least 32, including 2 children","June 21, 2026: US CENTCOM rebutted Iran's Hormuz closure claim, reporting 55 merchant ships carrying 17M+ barrels transited the Strait on June 20; Trump threatened US tolls on Hormuz transit if a final deal is not reached within the 60-day ceasefire window",
    "June 19, 2026: Hezbollah killed 4 Israeli soldiers in a cross-border attack; Israel retaliated with strikes on 80+ targets across Lebanon, killing at least 83 and wounding 141, per the Lebanese Health Ministry's final toll — the war's second-deadliest day — before a US/Qatar-brokered ceasefire took effect at 4pm local time; the IDF says it will keep forces in southern Lebanon and remains ready to resume fighting","June 18–19, 2026: The planned Bürgenstock implementation talks collapsed before they began as Pakistan's PM Sharif, US VP Vance, and Iran's own delegation all withdrew — Iran's delegation citing continued Israeli strikes in Lebanon — leaving Lebanon's status within the ceasefire unresolved ahead of the now-confirmed June 23-25 Washington Israel-Lebanon talks","June 17, 2026: IDF assault on the Ali al-Taher hill near Nabatieh repelled by Hezbollah in fierce fighting — ground combat continues even as the US-Iran MoU was signed the same day","June 1, 2026: Israel-Hezbollah preliminary ceasefire (Israel: no Beirut suburb strikes; Hezbollah: no attacks on Israel) immediately under threat from continued cross-border attacks; June 3–4 Lebanon-Israel Washington ceasefire deal rejected by Hezbollah — Kassem called it 'absurd, humiliating and insulting'; a fifth round of direct talks is now confirmed for Washington, DC on June 23-25; June 14: US-Iran ceasefire deal announced includes Lebanon in cessation of hostilities","June 16, 2026: Iran's FM Araghchi said continued Israeli occupation of seized Lebanese territory or further attacks would violate the US-Iran MoU; Israel rejected this — Netanyahu confirmed IDF will not withdraw, Ben-Gvir said 'Trump's agreement does not bind us' — leaving Lebanon's status within the ceasefire unresolved days before the June 19 signing","June 14, 2026: Israel issued forced displacement orders for 29 towns in southern Lebanon and struck Beirut's southern suburbs, killing at least 3 — escalation despite the announced regional ceasefire","Israeli strikes killed 4 in Lebanon on June 4 as Hezbollah-Israel exchanges intensified after ceasefire collapse","June 14, 2026 (hours after the US-Iran ceasefire announcement): Hezbollah drones struck northern Israel; Israel retaliated by striking a Hezbollah command centre in Beirut's Dahiyeh district; Iran vowed retaliation — raising doubt the Lebanon front will hold ahead of the June 19 signing","2026 Lebanon war — Hezbollah re-escalated alongside Iran's retaliation; April 16 ceasefire and 45-day extension now broken","Israel launched new strikes May 18 including Baalbek airstrike that killed an Islamic Jihad commander","Ongoing economic depression — 80%+ poverty rate, collapsed banking system","Reconstruction of the south halted by renewed hostilities","Sectarian power-sharing system structurally incapable of reform"] },
  "430":{ name:"Liberia", level:2, summary:"Liberia has maintained peace since its civil wars ended. Challenges include weak institutions, corruption, and economic underdevelopment.", reasons:["Weak state institutions and judicial capacity","Corruption hampering development","Youth unemployment and poverty"] },
  "434":{ name:"Libya", level:4, summary:"Libya remains divided between two rival governments. Foreign powers back opposing sides, preventing unification more than a decade after the 2011 revolution.", reasons:["Two rival governments controlling different halves of country","Haftar's LNA vs. GNU — ongoing division and clashes","Foreign military presence: Turkey, Russia, UAE, Egypt","Migrant smuggling networks destabilizing the state"] },
  "466":{ name:"Mali", level:4, summary:"Mali's military junta expelled French and UN forces and invited Russian Wagner Group mercenaries. Jihadist groups have expanded territory dramatically and the junta has pulled out of ECOWAS.", reasons:["Military junta expelling French/UN forces, inviting Wagner","Jihadist groups (JNIM linked to Al-Qaeda) controlling vast territory","Withdrawal from ECOWAS and regional isolation","Humanitarian crisis with millions displaced"] },
  "484":{ name:"Mexico", level:3, summary:"Mexico faces a security crisis driven by powerful drug cartels that outgun the state in many regions. Journalist and politician assassinations are at record levels.", reasons:["Cartel territorial wars causing 30,000+ homicides annually","Cartel infiltration of state and municipal governments","Mass disappearances — 100,000+ missing persons","Journalist and candidate assassinations","US-Mexico tensions over fentanyl trafficking"] },
  "496":{ name:"Mongolia", level:1, summary:"Mongolia is a stable parliamentary democracy between Russia and China. Its main vulnerability is economic dependency on both neighbors and corruption within the political system.", reasons:["Geopolitical squeeze between Russia and China","Mining resource corruption","Economic volatility from commodity prices"] },
  "504":{ name:"Morocco", level:2, summary:"Morocco has modernized under King Mohammed VI but maintains an authoritarian system. The Western Sahara territorial dispute remains a chronic flashpoint.", reasons:["Western Sahara territorial dispute with Polisario/Algeria","Suppression of Hirak Rif protest movement","Press freedom restrictions and political prisoners"] },
  "508":{ name:"Mozambique", level:3, summary:"Mozambique faces a long-running jihadist insurgency in Cabo Delgado province (linked to ISIS). Disputed 2024 elections also triggered deadly protests nationwide.", reasons:["ISIS-linked insurgency in Cabo Delgado","1 million displaced by northern insurgency","Post-election violence following disputed 2024 results"] },
  "516":{ name:"Namibia", level:1, summary:"Namibia is one of Africa's more stable democracies, though it faces significant inequality and debates over colonial-era land restitution.", reasons:["Extreme economic inequality and land ownership disparities","German colonial reparations dispute","Youth unemployment"] },
  "524":{ name:"Nepal", level:2, summary:"Nepal's March 2026 elections gave Balendra Shah's RSP a commanding majority (182/275 seats), ending years of unstable coalition governments. Shah — a rapper, structural engineer, and former Kathmandu mayor — was sworn in as PM on March 27, 2026 at age 35, Nepal's youngest PM. The election followed 2025 Gen Z-led protests that toppled the prior government. India-China strategic competition and border disputes remain structural challenges.", reasons:["India-China strategic competition over Nepal's geopolitical alignment","Border disputes with India (Kalapani, Lipulekh, Limpiyadhura areas)","Economic dependency on India for trade and remittances","New government untested — policy delivery and coalitional durability uncertain","Remote mountainous terrain limiting development and state reach"] },
  "528":{ name:"Netherlands", level:1, summary:"The Wilders-led PVV coalition collapsed in June 2025 after just 11 months. D66 leader Rob Jetten formed a three-party minority coalition (D66, VVD, CDA) sworn in on February 23, 2026 — the Netherlands' youngest-ever PM and first from D66. The minority government holds only 66 of 150 seats and must negotiate opposition support for every measure.", reasons:["Minority government fragility — 66/150 seats requires constant cross-aisle negotiation","Wilders' PVV in vocal opposition, publicly denouncing the Jetten government","Immigration and integration policy remains a highly contested fault line","Defence spending increase demands straining fiscal space","Legacy of short-lived Schoof cabinet and political instability"] },
  "558":{ name:"Nicaragua", level:4, summary:"Nicaragua under Daniel Ortega is a full authoritarian state. The Catholic Church has been persecuted, all opposition parties banned, independent media shuttered, and hundreds of political prisoners held.", reasons:["Ortega's authoritarian consolidation after 2018 crackdown","Persecution and expulsion of Catholic clergy","All meaningful political opposition banned","Hundreds of political prisoners","Independent media entirely eliminated"] },
  "562":{ name:"Niger", level:4, summary:"Niger's 2023 military coup ousted President Bazoum and expelled French forces. The junta joined Mali and Burkina Faso in the Alliance of Sahel States, pulling away from Western security partnerships.", reasons:["Military junta rule since July 2023 coup","French and US forces expelled","Jihadist violence (JNIM, ISGS) continuing","Withdrawal from ECOWAS and regional isolation","Alliance with Mali and Burkina Faso military juntas"] },
  "566":{ name:"Nigeria", level:3, summary:"Nigeria faces multiple simultaneous security crises: Boko Haram/ISWAP in the northeast, banditry in the northwest, Biafra separatism in the southeast, and Fulani-farmer conflict in the Middle Belt.", reasons:["ISWAP/Boko Haram terrorism in northeast","Bandit gangs controlling northwest states","Biafra (IPOB) separatist movement","Farmer-herder communal violence","Economic crisis: naira collapse and inflation"] },
  "586":{ name:"Pakistan", level:4, summary:"Pakistan is simultaneously managing a political crisis, a raging insurgency, and a frozen conflict with India. In May 2025, Pakistan and India exchanged cross-border missile and drone strikes for four days (Operation Sindoor / Bunyan-um-Marsoos); a ceasefire was agreed May 10. India suspended the Indus Waters Treaty, bilateral trade, and visa services. Former PM Imran Khan remains imprisoned. After an Islamabad suicide bombing, Pakistan declared 'open war' on Afghanistan's Taliban regime and launched Operation Ghazab Lil Haq on February 26, 2026, striking over 70 targets including Bagram Airbase and Kabul over alleged TTP safe havens; Afghanistan retaliated with cross-border attacks. Ceasefires mediated by Qatar, China, and Eid-holiday truces have repeatedly collapsed, with low-intensity cross-border fighting continuing as of mid-June 2026.", reasons:["May 2025 military conflict with India — four days of cross-border strikes; nuclear escalation risk was acute","India suspended Indus Waters Treaty, trade, and visa services — relations frozen with no normalisation","Imran Khan imprisoned — PTI suppressed but retains massive popular support","Open war with Afghanistan since February 2026 (Operation Ghazab Lil Haq) over TTP safe havens — strikes on Bagram Airbase and Kabul; repeated mediated ceasefires have collapsed","Military's ISI continuing to dominate civilian political space","Balochistan separatist insurgency intensifying alongside TTP attacks"] },
  "591":{ name:"Panama", level:2, summary:"Panama saw massive protests in 2023 over a copper mine contract. Canal strategic importance creates geopolitical pressures and US pressure over migration flows through the Darién Gap.", reasons:["Copper mine (Cobre Panama) controversy and protests","Canal strategic importance creating geopolitical pressures","US pressure over migration flows through Darién Gap","Corruption scandals affecting public trust"] },
  "604":{ name:"Peru", level:3, summary:"Peru has had six presidents in six years. President Boluarte took power after Castillo's self-coup attempt. Congress and the executive remain locked in conflict.", reasons:["Extreme political instability — 6 presidents in 6 years","2022-23 protests suppressed with deadly force","Ongoing conflict between executive and Congress","High corruption at all levels of government"] },
  "608":{ name:"Philippines", level:3, summary:"The Philippines faces a dramatic political break between President Marcos Jr. and the Duterte family, while China's aggressive actions in the South China Sea create constant maritime tensions.", reasons:["China's aggressive harassment of Philippine vessels","Philippine-China water cannon and ship collision incidents","Marcos-Duterte political alliance collapse","Communist New People's Army (NPA) insurgency","Abu Sayyaf jihadist group in Mindanao"] },
  "616":{ name:"Poland", level:2, summary:"Poland transitioned from the nationalist PiS government to a pro-EU coalition under PM Tusk. The new government faces the challenge of restoring judicial independence while managing its eastern border amid the Ukraine war.", reasons:["Ukraine war on neighboring border — direct security threat","Russia and Belarus orchestrating hybrid migration at borders","Domestic tensions over reversing PiS judicial changes","Deepening societal polarization between PiS and Tusk blocs"] },
  "634":{ name:"Qatar", level:2, summary:"Qatar has navigated the Gulf blockade crisis and used the 2022 FIFA World Cup for soft power, but faces criticism over migrant worker conditions. It plays a key mediation role in Gaza ceasefire talks.", reasons:["Criticism over migrant worker kafala system and deaths","Regional rivalries with Saudi Arabia and UAE","Hamas political bureau hosting creating Western tensions","Balancing Iran and Gulf state relations"] },
  "643":{ name:"Russia", level:5, summary:"Russia continues its full-scale war against Ukraine into its fourth year. Ceasefire negotiations mediated through US-Russia direct talks (restarted under Trump) have produced a 72-hour ceasefire (May 9–11) that was largely violated by both sides. Putin's Victory Day declaration that the war is 'coming to an end' and his offer of direct talks signal possible momentum, though US-brokered Geneva peace talks (most recent: February 2026, third round of trilateral talks) ended without breakthrough and the US-imposed June 2026 deadline for a deal is now upon both sides — territorial control of Donetsk remains the central sticking point. A further round of US-brokered trilateral talks in Abu Dhabi in mid-June also produced no breakthrough, with Russia pressing Ukraine to fully withdraw from Donbas — a demand Kyiv rejects; new trilateral talks have been proposed in Miami. North Korean troops remain integrated into Russian units. On May 24–25, Russia launched one of the largest drone and missile attacks on Kyiv since 2022, including Oreshnik hypersonic missiles; at least 4 people were killed and over 90 injured. Russia's Foreign Ministry warned foreigners to leave Kyiv. On June 18, Ukraine retaliated with its largest drone attack on Moscow since the war began, striking the Kapotnya oil refinery — which supplies over a third of the Moscow region's fuel — for the second time that week; Russia said its defences downed roughly 555 drones overall, but the strikes still disrupted Moscow airport operations and closed major roads. Zelenskyy cast the attack as retaliation for Russian strikes on a historic Ukrainian monastery and warned that 'Moscow will burn' if Putin continues the war.", reasons:["Full-scale war against Ukraine with no end in sight — 4th year","US-brokered Geneva peace talks (Feb 2026) ended without breakthrough; US June 2026 peace deadline now reached — Donetsk territorial control the central obstacle","North Korean troops integrated into Russian frontline units","May 24–25 massive drone/missile attack on Kyiv including Oreshnik hypersonic — 4 killed, 90+ injured; Russia Foreign Ministry warned foreigners to leave Kyiv","June 18, 2026: Ukraine's largest drone attack on Moscow since the war began hit the Kapotnya oil refinery (second time that week), disrupting airport operations; Zelenskyy warned 'Moscow will burn' if the war continues","Economy overheating — 21%+ interest rates, labour shortages, inflation","Political prisoners — post-Navalny era with all dissent criminalized","Nuclear rhetoric used as strategic deterrent against Western escalation"] },
  "646":{ name:"Rwanda", level:4, summary:"Rwanda's direct military support for DRC's M23 rebels has crossed into open international confrontation. The United States sanctioned Rwanda's army and four senior officials (March 3, 2026) for 'direct operational support' of M23 following the fall of both Goma and Bukavu. DRC severed full diplomatic relations with Rwanda.", reasons:["US sanctions on Rwandan army and senior officials (March 2026) for M23 support","DRC severed full diplomatic relations with Rwanda (March 2026)","Direct troop involvement in eastern DRC — Goma and Bukavu now under M23/Rwandan control","International isolation deepening as M23 offensive expands","Authoritarian governance with no meaningful political opposition","Assassinations of opponents abroad"] },
  "682":{ name:"Saudi Arabia", level:4, summary:"Saudi Arabia has been directly struck by Iranian missiles and drones as part of Iran's retaliation campaign. The IRGC's closure of the Strait of Hormuz — through which the bulk of Saudi oil exports transit — directly threatens Vision 2030 funding. Saudi Arabia is attempting to stay out of the US-Israel-Iran war while managing extreme regional pressure from all sides.", reasons:["Iran directly struck Saudi Arabia in its retaliation campaign — unprecedented direct attack","Strait of Hormuz closure threatens Saudi oil export routes","MBS balancing act: refusing to join US coalition while resisting Iranian aggression","Gaza war remains politically toxic domestically; Saudi-Israel normalisation fully frozen","Yemen: Houthi attacks continue; risk of Houthi entrenching as Iran-backed permanent power","Houthi missile and drone attacks on Saudi territory still ongoing amid Iran conflict"] },
  "686":{ name:"Senegal", level:2, summary:"Senegal had a tense 2024 political crisis when former President Sall attempted to delay elections, but backed down after mass protests. New President Faye has taken office in a historic democratic renewal.", reasons:["2024 election crisis — delayed vote attempt and protests","Separatist conflict in Casamance region (low intensity)","Economic pressures and youth unemployment"] },
  "688":{ name:"Serbia", level:3, summary:"Serbia under Vucic balances between EU integration and alignment with Russia and China. Mass anti-corruption protests erupted in 2024-25 after a train station roof collapse. Kosovo's independence remains an irresolvable flashpoint.", reasons:["Kosovo independence dispute — Serbia refuses recognition","Mass anti-corruption protests following Novi Sad station collapse","Balancing EU membership aspirations with Russia/China ties","Suppression of media and political opposition"] },
  "706":{ name:"Somalia", level:5, summary:"Somalia remains one of the world's most fragile states. A constitutional crisis erupted on May 15, 2026 when President Hassan Sheikh Mohamud's four-year term expired; parliament had passed amendments in March 2026 extending terms from four to five years, but opposition factions condemned this as a 'constitutional coup' and refuse to recognise Mohamud. Puntland and Jubbaland have declared non-recognition of his authority post-May 15. Heavy fighting erupted in Baidoa on May 14 between Somali federal government forces and troops loyal to former South West State president Abdiaziz Hassan Mohamed. On June 3–4, 2026, heavy gunfire erupted in central Mogadishu — described as the deadliest unrest in the capital in years — as government forces attacked former Prime Minister Hassan Ali Khaire ahead of planned protests; two days of fighting paralysed central Mogadishu, killing at least 13 and wounding 189, with 12,500+ households fleeing. The government declared order restored on June 5, but fighting resumed on the northern outskirts of Mogadishu on June 7 near El Macaan village, between federal forces and Ma'awisley militias loyal to former Security Minister Abdullahi Mohamed Nur — showing Western diplomatic pressure has only suppressed, not resolved, the standoff. Al-Shabaab continues to control significant rural territory and carry out frequent deadly attacks.", reasons:["June 3–5, 2026: Government forces attacked former PM Hassan Ali Khaire before planned protests; two days of fierce fighting killed at least 13, wounded 189, forced 12,500+ households to flee — described as the deadliest unrest in the capital in years; government declared order restored June 5 but constitutional crisis unresolved","June 7, 2026: Renewed fighting near El Macaan village north of Mogadishu between federal forces and Ma'awisley militias loyal to former Security Minister Abdullahi Mohamed Nur, days after diplomatic pressure ended the capital clashes","Constitutional crisis since May 15, 2026 — parliament's March 2026 term-extension amendments condemned as 'constitutional coup'; Puntland and Jubbaland refuse to recognise Mohamud; US mediating at Mogadishu's Halane compound; initial negotiations have collapsed","Heavy fighting erupted in Baidoa (May 14, 2026) between Somali federal forces and troops loyal to former South West State president Abdiaziz Hassan Mohamed — kinetic escalation alongside the constitutional crisis","Al-Shabaab controlling major rural areas and carrying out deadly attacks in Mogadishu and beyond","Fundamental disagreement over electoral model: president demands direct vote; opposition insists on indirect process","Chronic drought and food insecurity"] },
  "716":{ name:"Zimbabwe", level:3, summary:"Zimbabwe under Mnangagwa's ZANU-PF remains an authoritarian state with a collapsed economy. Opposition suppression and human rights abuses persist.", reasons:["ZANU-PF authoritarian rule and manipulation of elections","Economic collapse and high poverty","Suppression of opposition","Widespread political repression","Land reform legacy creating food insecurity"] },
  "724":{ name:"Spain", level:2, summary:"Spain manages tensions over Catalan independence — the major separatist leaders received amnesty in 2024. Coalition politics under PM Sanchez are fragile and the far-right Vox party is a significant force.", reasons:["Catalan independence movement — amnesty law controversy","Fragile parliamentary coalition requiring separatist support","Far-right Vox party growing political influence","Basque ETA legacy and ongoing separatist sentiment"] },
  "728":{ name:"South Sudan", level:5, summary:"South Sudan has effectively returned to civil war. Fighting between forces loyal to President Kiir and VP Machar's SPLM-IO erupted in 2025, shattering the Revitalized Peace Agreement. Multiple states face active combat and the UN has warned of mass atrocity risks.", reasons:["Return to active civil war between Kiir and Machar forces (2025)","Peace agreement (R-ARCSS) collapsed — security mechanisms non-functional","Famine-level food insecurity affecting millions","Over 4 million refugees in neighbouring countries","Sudan's own civil war has cut off vital supply corridors","International community capacity severely strained by multiple crises"] },
  "729":{ name:"Sudan", level:5, summary:"Sudan's civil war between the SAF and RSF has entered its fourth year (since April 2023). The SAF retook Khartoum in March 2025 and the military-led government returned to the capital in January 2026. Fighting is intensifying in Kordofan and Darfur, with drone strikes targeting civilian infrastructure — drone strikes alone killed more than 1,000 civilians in the first five months of 2026. The conflict has created the world's largest humanitarian crisis. On June 3, 2026, Egyptian, Saudi, and Emirati officials met with US Deputy Secretary of State Christopher Landau and Africa adviser Massad Boulos in Washington to revive the 'Quad' Sudan peace push, setting the stage for Egyptian President Sisi to travel to Abu Dhabi for follow-up talks with UAE President Mohammed bin Zayed — but no ceasefire has yet followed on the ground.", reasons:["Civil war between SAF and RSF since April 2023 — entering 4th year","RSF ethnic cleansing in Darfur — genocide allegations","World's largest displacement crisis (13.6+ million displaced)","Collapse of health system and famine officially confirmed in multiple states","Drone warfare sharply escalating — over 1,000 civilians killed by drone strikes in Jan–May 2026 alone","Foreign involvement: UAE alleged to back RSF; Egypt supports SAF","June 3, 2026: US-Egypt-Saudi-UAE 'Quad' talks (Deputy Secretary Landau, Africa adviser Boulos) revived the Sudan peace push, followed by Sisi-MBZ talks in Abu Dhabi — but no ceasefire has materialised"] },
  "740":{ name:"Suriname", level:2, summary:"Suriname is navigating major offshore oil discoveries with fiscal and governance challenges.", reasons:["Oil wealth management and governance capacity concerns","Historical political instability legacy","High debt and economic challenges"] },
  "756":{ name:"Switzerland", level:1, summary:"Switzerland is consistently among the world's most stable and peaceful countries. Its neutrality has been tested by pressure to align with EU sanctions on Russia.", reasons:["Debate over neutrality vs. supporting Ukraine sanctions","Immigration and asylum policy political debates"] },
  "760":{ name:"Syria", level:3, summary:"Following Assad's fall in December 2024, the HTS-led transitional government under Ahmad al-Sharaa has maintained a degree of order in Damascus and is seeking international legitimacy. Some Western sanctions have been eased. Significant risks remain from multiple armed factions, continued ISIS activity, and Turkish-Kurdish tensions in the northeast.", reasons:["Fragile HTS-led transitional government with limited nationwide authority","Turkish military operations against Kurdish SDF in northeast","Continued ISIS attacks particularly in desert regions","Millions of refugees not yet returning; country's infrastructure devastated","Competing armed factions — rebel coalitions, Druze militias, SDF","Israel conducting strikes on Syrian military sites post-Assad"] },
  "762":{ name:"Tajikistan", level:3, summary:"Tajikistan is an authoritarian state bordering Afghanistan. The Taliban's takeover has heightened security concerns, and border conflicts with Kyrgyzstan have caused significant casualties.", reasons:["Taliban-controlled Afghanistan on border","2022 border war with Kyrgyzstan","Authoritarian Rahmon family dynastic rule","Drug trafficking corridor from Afghanistan"] },
  "764":{ name:"Thailand", level:4, summary:"PM Anutin Charnvirakul's Bhumjaithai Party won the February 2026 elections with 192 seats, defeating the progressive People's Party (120 seats); Anutin was reconfirmed as PM on March 19, 2026 — the first Thai PM re-elected in two decades. An active border military conflict with Cambodia erupted in May 2025 and escalated dramatically in July 2025; a ceasefire was declared December 27, 2025, but continued armed incidents and mutual distrust persist. The combination of the border conflict, domestic political tensions, and the decades-long southern separatist insurgency keeps Thailand's risk level elevated.", reasons:["Active border military conflict with Cambodia (May 2025–): major escalation July 2025; ceasefire (Dec 27, 2025) fragile — US Embassy security alerts for continued armed conflict in 2026; over 409,000 displaced on the Cambodian side","People's Party (former Move Forward) in strong opposition with 116+ seats — risk of continued judicial-political clashes","Constitutional Court's removal of PM Paetongtarn Shinawatra (August 2025) — judiciary-politics tension unresolved","Youth movement demanding monarchy reform — significant underlying pressure","Regional separatist insurgency in deep south — decades-long low-level conflict","Military-royalist institutional influence persists despite democratic election results"] },
  "784":{ name:"United Arab Emirates", level:3, summary:"The UAE faces a significant new direct security threat after Iran launched its first-ever attack on UAE territory on May 4–5, 2026: 15 ballistic missiles and 4 drones struck Fujairah, causing a fire at an oil facility. UAE air defences intercepted most projectiles. The unprecedented direct attack marks a major escalation of security risk to the hub economy and investor confidence. The UAE continues to navigate a delicate balance: deeply tied to US/Western security while maintaining economic relationships with Iran and Russia.", reasons:["Iran's first-ever direct missile and drone attack on UAE (May 4–5, 2026) — unprecedented security escalation","15 ballistic missiles and 4 drones struck Fujairah oil facility — investor confidence impact","Authoritarian governance with no political opposition or free press","Abraham Accords-Israel normalisation under political strain from ongoing Gaza and Lebanon wars","Hosting sanctioned Russian and Iranian business — Western diplomatic friction","Labour rights concerns — migrant workers under kafala system"] },
  "788":{ name:"Tunisia", level:3, summary:"Tunisia, the Arab Spring's only initially successful democracy, has reverted to authoritarianism under President Saied, who dissolved parliament in 2021 and has imprisoned opposition leaders.", reasons:["Presidential coup concentrating all power in Saied","Imprisonment of opposition leaders, journalists, and judges","New constitution eliminating democratic checks","Economic crisis and high unemployment"] },
  "792":{ name:"Turkey", level:3, summary:"Turkey under Erdoğan faces significant domestic tensions. The March 2025 arrest of Istanbul Mayor Ekrem İmamoğlu — the main opposition presidential candidate — triggered the largest mass protests in over a decade. In March 2026, Turkey, Pakistan, and Azerbaijan formalized a new geostrategic alignment dubbed the 'Three Brothers' military axis, signalling a deepening of ties outside NATO structures.", reasons:["Arrest of Istanbul Mayor İmamoğlu triggering major protests (March 2025)","Systemic erosion of judicial independence and press freedom","Kurdish PKK conflict and Turkish military operations in Syria/Iraq","Inflation easing from 85% peak but still high; lira weak","Balancing NATO membership with independent Russia and Iran relationships","'Three Brothers' military axis with Pakistan and Azerbaijan (March 2026) — new alignment outside NATO structures"] },
  "800":{ name:"Uganda", level:3, summary:"Uganda under Museveni (in power since 1986) passed the world's harshest anti-LGBTQ law in 2023, drawing international condemnation and sanctions. ADF insurgency and DRC instability add security dimensions. In May 2026, a WHO PHEIC-designated Ebola (Bundibugyo ebolavirus) outbreak that originated in eastern DRC spread to Uganda including cases in Kampala by May 21. By June 15, Uganda had 19 confirmed cases (2 deaths) — up from 7 confirmed (1 death) in late May — while DRC's confirmed case count had surged to 808 (192 deaths); with no available vaccine for this strain, the WHO has expressed deep concern over the outbreak's continued growth.", reasons:["Draconian anti-LGBTQ law with death penalty provisions","Museveni's 38-year authoritarian rule","Western sanctions over human rights abuses","ADF (ISIS-linked) insurgency in western Uganda","WHO-declared Ebola Bundibugyo ebolavirus PHEIC (May 16, 2026) continues to grow — Uganda confirmed cases rose to 19 (2 deaths) by June 15 as DRC's confirmed total surged to 808 (192 deaths); no Bundibugyo vaccine exists"] },
  "804":{ name:"Ukraine", level:5, summary:"Ukraine is in its fourth year of full-scale war with Russia. A US-brokered 72-hour ceasefire (May 9–11) was agreed but largely violated by both sides; Putin has signalled openness to direct negotiations while continuing military pressure. US military aid remains uncertain. EU financial and military support has increased. Three rounds of US-brokered Geneva talks (most recent: February 2026) ended without breakthrough; the US-imposed June 2026 deadline for both sides to reach a deal is now upon them — territorial control of Donetsk is the central sticking point. A further round of trilateral talks in Abu Dhabi in mid-June also failed to produce a breakthrough, with Russia demanding a full Ukrainian withdrawal from Donbas; Zelenskyy says the US has proposed new trilateral talks in Miami, which Ukraine will attend. On May 24–25, Russia launched one of its largest drone and missile attacks on Kyiv since 2022, including Oreshnik hypersonic missiles; at least 4 people were killed and over 90 injured. Russia's Foreign Ministry warned foreigners to leave Kyiv. On June 18, Ukraine launched its largest drone attack on Moscow since the war began, striking the Kapotnya oil refinery — over a third of the Moscow region's fuel supply — for the second time that week, in retaliation for Russian strikes on a historic Ukrainian monastery; Zelenskyy said it was 'time the war ended' and warned 'Moscow will burn' if Putin persists. The attack disrupted Moscow airport operations and closed major roads despite Russia downing roughly 555 drones overall.", reasons:["Active full-scale war with Russia — frontline under pressure in Donetsk","US-brokered Geneva peace talks (Feb 2026) ended without breakthrough; US June 2026 peace deadline now reached — risk of unfavorable imposed settlement remains","US military aid uncertain — ongoing policy shifts","EU has stepped up financial and military support","May 24–25 massive Russian attack on Kyiv: Oreshnik hypersonic missile and large drone/missile barrage — 4 killed, 90+ injured; one of largest attacks since 2022","June 18, 2026: Ukraine's largest drone strike on Moscow since the war began hit the Kapotnya oil refinery (second time that week) in retaliation for a Russian strike on a historic monastery — Zelenskyy: 'time the war ended'","Energy infrastructure repeatedly targeted — millions without heat/power in winter","Demographic crisis: casualties, emigration, low birth rate"] },
  "818":{ name:"Egypt", level:3, summary:"Egypt under President Sisi maintains order through authoritarian control, but faces economic crisis including IMF dependency, currency devaluation, and Gaza-generated pressure on Sinai.", reasons:["Gaza war pressures — potential refugee influx risk","Severe economic crisis: currency crisis, inflation, debt","Political prisoners numbering in the tens of thousands","Muslim Brotherhood suppression","Sinai jihadist insurgency","Nile dam dispute with Ethiopia"] },
  "826":{ name:"United Kingdom", level:2, summary:"The UK is in its deepest political crisis since Brexit. Labour suffered catastrophic losses in the May 2026 local elections — losing ~1,500 council seats in England and being swept from power in Wales after 27 years — while Reform UK gained ~1,454 seats. Health Secretary Wes Streeting resigned on May 14 citing lost confidence in Starmer's leadership, and launched a Labour leadership bid. Andy Burnham (Greater Manchester Mayor) was confirmed as Labour's candidate for the Makerfield by-election — triggered by Josh Simons standing down on May 14 — providing Burnham a parliamentary path to formally mount a leadership challenge. Defence Secretary John Healey resigned on June 11 with a scathing critique of the government's defence spending plans, followed by junior minister Al Carns and ministerial aide Pamela Nash — deepening the cabinet crisis just as the Makerfield by-election loomed. On June 18, Burnham won Makerfield with 54.8% of the vote (a 9,241-vote, 20.3-point majority over Reform UK), returning him to Westminster after eight years and giving him the parliamentary seat needed to formally challenge Starmer for the Labour leadership. Over 95 Labour MPs have called for Starmer to resign; he has resisted. Institutions remain functional but political stability has sharply deteriorated.", reasons:["June 18, 2026: Andy Burnham won the Makerfield by-election (54.8%, 9,241-vote majority over Reform UK), securing the Commons seat needed to formally challenge Starmer for the Labour leadership","June 11, 2026: Defence Secretary John Healey resigned over inadequate defence spending plans, followed by junior minister Al Carns and aide Pamela Nash — further eroding Starmer's authority","Labour's catastrophic May 2026 local election losses — ~1,500 council seats lost in England, ejected from Wales after 27 years","Reform UK gains ~1,454 seats across England — a dramatic political realignment","Health Secretary Streeting resigned May 14 citing lost confidence; four junior ministers (incl. Jess Phillips) and four ministerial aides also resigned; 95+ Labour MPs calling for Starmer to step down","Scottish independence movement and post-Brexit economic adjustment ongoing","Northern Ireland post-Brexit protocol tensions"] },
  "840":{ name:"United States", level:4, summary:"The United States continues its military campaign against Iran (Operation Epic Fury, since February 28, 2026), which killed Supreme Leader Khamenei. Trump extended a ceasefire on April 21 at Pakistan's request, but the US Navy blockade of Iranian ports continues. Iran has retaliated against US military bases across the Middle East and struck nine countries including the UAE for the first time on May 4–5. On May 4, Trump launched Operation Project Freedom — a US Navy mission to escort merchant vessels through the Strait of Hormuz — but very few commercial ships have risked the Iranian gauntlet. US and Iranian forces exchanged fire in the Strait around May 7; Trump characterised the incident as a 'love tap' and insisted the ceasefire remains in effect. On May 17–20, Trump called the ceasefire 'on massive life support' after rejecting Iran's proposal; Iran submitted a revised nuclear offer and Pakistan pressed both sides urgently ('we don't have much time'). On May 23, Trump announced the deal is 'largely negotiated'; May 24 reporting revealed specific framework terms: 60-day ceasefire, Hormuz reopening, Iran oil sales, US sanctions waivers, and nuclear talks. The Strait remains closed; on May 26, US CENTCOM struck Iranian missile launch sites and mine-laying boats in self-defense operations. On May 27, US forces struck additional Iranian military sites in southern Iran; Iran accused the US of a 'grave ceasefire violation'. On May 28, CNN reported the US and Iran had reached a tentative agreement, though Trump had not signed off. On May 29, Trump added new demands — on Hormuz navigation, Iran's nuclear program, and frozen overseas assets — that 'didn't go down well in Tehran.' On May 30, Bloomberg reported the US insists deals for safe Hormuz transit are 'prohibited'; Iran reasserted control over the Strait. VP Vance confirmed MoU signing is 'TBD' as the two sides negotiate 'a couple of language points.' Defense Secretary Hegseth stated the US military is ready to resume combat if required. The deal remains elusive. On June 1, Iranian state media reported talks suspended over Israel's Lebanon actions; Trump insisted June 2 that talks are ongoing and a deal is reachable 'over the next week.' The US Senate passed a preliminary War Powers Resolution vote 50–47 on May 26, requiring a halt to hostilities not approved by Congress. The worst global shipping disruption since the 1970s continues, compounding the impact of 145%+ tariffs on China. Domestically, Trump's second term continues reshaping the constitutional order through DOGE, agency dismantling, and executive overreach. On June 9, Iran launched retaliatory strikes on US military bases in Bahrain and Jordan. On June 10, US forces struck Iranian military targets in Jask, Qeshm, and Bandar Abbas in a further escalation. On June 11, US forces fired 49 Tomahawk missiles at Iranian targets; Iran responded by declaring a complete Strait of Hormuz closure including to all oil tankers and commercial ships; Trump threatened to seize Kharg Island (Iran's main oil hub, handling ~90% of its exports) and 'other oil infrastructure points' before later cancelling further strikes citing discussions with Iran. On June 12, the IAEA declared Iran in breach of its non-proliferation obligations, and UN Secretary-General Guterres warned of the risk of return to 'full war.' On June 13, Pakistan's PM Shehbaz Sharif announced that the US and Iran have agreed on the 'final' wording of a peace deal, raising hopes of an imminent ceasefire and Hormuz reopening. On June 14, the US and Iran formally announced a ceasefire agreement — the Islamabad Memorandum, to be signed at Bürgenstock, Switzerland on June 19 — including immediate cessation of hostilities on all fronts (including Lebanon), toll-free Strait of Hormuz navigation, Iran's indefinite nuclear weapons prohibition, and lifting of the US naval blockade; oil prices fell to ~$83/barrel on the announcement. On June 15, Trump and VP Vance digitally signed the MoU at the White House, with Iranian Parliament Speaker Ghalibaf signing for Tehran, ahead of the in-person Switzerland ceremony; the deal's text has not been released and it triggers 60 days of nuclear negotiations. On June 16, a dispute emerged over the deal's scope: Iran's FM Araghchi warned that Israeli attacks on Lebanon or continued occupation would violate the MoU, while Israeli officials — including Netanyahu and Ben-Gvir — said Israel would not withdraw from seized territory and is not bound by the agreement. On June 17, at the conclusion of the G7 summit in Évian-les-Bains, Trump personally signed the memorandum in person at a state dinner hosted by President Macron at the Palace of Versailles, with Iran's President Pezeshkian co-signing remotely — even as Israeli forces fought to seize the Ali al-Taher hill near Nabatieh in southern Lebanon that same day, underscoring that the Lebanon front remains active ahead of the planned June 19 Bürgenstock implementation talks. Brent crude extended its slide to ~$78–79/barrel by June 18, its lowest since early March. On June 18–19, those planned Bürgenstock implementation talks collapsed before they began: Pakistan's PM Sharif cancelled his trip once it was clear the MoU had already been signed electronically and at Versailles, US VP Vance postponed his own travel citing unresolved logistics, and Iran's delegation suspended its departure in protest at continued Israeli strikes in Lebanon. Strait of Hormuz commercial transits remain at only 5–10% of pre-war volume, with industry analysts (Kpler) projecting a recovery to roughly half of prewar levels within 30 days if talks resume. A separate MoU provision committing the US to help develop a $300 billion Iran reconstruction fund — to be financed by Gulf and other partners rather than the US government — became a domestic political flashpoint on June 18-19, with Trump and VP Vance both denying the US itself would fund it; Khamenei said the same day he had approved the deal despite holding a 'different view.' On June 19, the Lebanon front flared again as Hezbollah killed 4 Israeli soldiers and Israeli retaliatory strikes killed at least 83 people and wounded 141 across Lebanon, per the Lebanese Health Ministry's final toll — the war's second-deadliest day — prompting the US and Qatar to broker a renewed ceasefire effective 4pm local time. That truce broke down within a day: on June 20, Hezbollah fired 50+ projectiles overnight at IDF positions and Israeli retaliatory strikes killed at least 32, including 2 children — underscoring the fragility of the Lebanon front even as Strait of Hormuz traffic showed tentative recovery (threat level cut to 'substantial' by JMIC/UKMTO on June 17; 25 vessels transited June 18, the busiest day in weeks, though still far below the 100+ pre-war daily average) and Brent crude steadied near $80/barrel on June 19. A fifth round of direct Israel-Lebanon talks is now confirmed for Washington, DC on June 23-25, while the separate Bürgenstock US-Iran implementation talks remain unscheduled. On June 21, US CENTCOM rebutted Iran's earlier Hormuz closure claim, reporting that 55 merchant ships carrying more than 17 million barrels of oil transited the Strait on June 20 alone, and Trump threatened to impose US tolls on Hormuz transit — framed as payment for America's 'Guardian Angel' role in the Middle East — if a final deal is not reached within the 60-day ceasefire window. Later on June 21, the Bürgenstock implementation talks — collapsed two days earlier — formally got underway at the Lake Lucerne hotel complex, with VP Vance leading the US delegation, Iranian Parliament Speaker Ghalibaf leading Tehran's, and Pakistan and Qatar mediating; Vance told reporters the priority was progress on the nuclear issue and the Lebanon ceasefire, launching the 60-day sprint on technical details.", reasons:["June 21, 2026: The Bürgenstock implementation talks formally launched at Lake Lucerne after their June 19 collapse, with VP Vance leading the US delegation and Speaker Ghalibaf leading Iran's, Pakistan and Qatar mediating — Vance named the nuclear issue and the Lebanon ceasefire as the two priorities for the 60-day technical sprint","June 20, 2026: Lebanon ceasefire broken again within a day — Hezbollah fired 50+ projectiles overnight; Israeli strikes killed at least 32 in southern Lebanon, including 2 children — while Hormuz traffic recovers only gradually (25 vessels June 18) and Bürgenstock implementation talks remain unscheduled","June 21, 2026: US CENTCOM rebutted Iran's Hormuz closure claim, reporting 55 merchant ships carrying 17M+ barrels transited the Strait on June 20; Trump threatened US tolls on Hormuz transit if a final deal is not reached within the 60-day ceasefire window",
    "June 19, 2026: US and Qatar brokered a renewed Israel-Hezbollah ceasefire after a Lebanon flare-up (4 Israeli soldiers killed; 83 killed and 141 wounded in Israeli retaliatory strikes, per the Lebanese Health Ministry's final toll) threatened to derail the broader US-Iran ceasefire process; a fifth round of direct Israel-Lebanon talks is now confirmed for Washington, DC on June 23-25","Active war with Iran — May 26–30: CNN (May 28) tentative agreement; May 29 Trump added new demands (Hormuz, nuclear, frozen assets) that 'didn't go down well in Tehran'; May 30 Bloomberg: US says Hormuz transit deals 'prohibited'; Iran reasserts Hormuz control; VP Vance: MoU signing 'TBD'; Hegseth warns US military ready to resume combat; War Powers Resolution passed Senate 50–47 (May 26) requiring halt to unauthorized hostilities; June 1: Iran suspended talks over Israel's Lebanon offensive; Trump June 2 insists talks continue, deal reachable 'over next week'; early June 2026: Trump submitted revised terms; ~June 5–6: two further US-Iran Strait skirmishes; June 6: US shot down Iranian drones and struck radar sites; June 9: Iran struck US military bases in Bahrain and Jordan; June 10: US struck Iranian military targets at Jask, Qeshm, and Bandar Abbas; June 11: US fired 49 Tomahawk missiles at Iran; Iran declared complete Hormuz closure including oil tankers and commercial ships; Trump threatened to seize Kharg Island, later cancelled further strikes citing Iran discussions; June 12: IAEA declared Iran in breach of non-proliferation obligations; UN SG Guterres warned of full war risk","Iran's retaliatory strikes on US military bases across Middle East, 9+ countries affected; UAE struck for first time (May 4–5)","Strait of Hormuz remains effectively closed — IRGC redefined it as 'vast operational area'; oil peaked $126/barrel","Iran-war economic shock compounding 145%+ China tariffs — IMF cut US 2026 growth to 2.3%","Executive overreach: DOGE, agency dismantling, alleged court order defiance","Extreme political polarization — institutions under stress with no modern precedent","June 14, 2026: US and Iran formally announced ceasefire deal — signing June 19 in Switzerland; includes cessation of hostilities on all fronts (including Lebanon), toll-free Hormuz navigation, Iran's indefinite nuclear weapons prohibition, lifting of US naval blockade; oil fell to ~$83/barrel","June 15, 2026: Trump and Vance digitally signed the US-Iran MoU (Ghalibaf signing for Iran) ahead of the June 19 Switzerland ceremony, kicking off 60 days of nuclear negotiations; June 16: dispute over Lebanon's inclusion — Araghchi warned continued Israeli occupation/attacks would violate the deal, while Netanyahu and Ben-Gvir said Israel is not bound and won't withdraw from seized territory","June 17, 2026: Trump personally signed the MoU in person at Versailles after the G7 summit in Évian-les-Bains, with Pezeshkian co-signing remotely for Iran, even as Israeli forces fought to seize Lebanon's Ali al-Taher hill the same day — Brent crude fell to ~$79/barrel by June 18, its lowest since early March","June 18–19, 2026: The planned Bürgenstock implementation talks collapsed before they began as Pakistan's PM Sharif, VP Vance, and Iran's own delegation all pulled out; Strait of Hormuz commercial traffic remains at just 5–10% of pre-war levels despite the ceasefire deal","June 18-19, 2026: The MoU's $300 billion Iran reconstruction fund — to be financed by Gulf and other partners rather than the US government — became a domestic political flashpoint, with Trump and VP Vance both denying the US itself would fund it; Khamenei said he approved the deal despite a 'different view'"] },
  "854":{ name:"Burkina Faso", level:4, summary:"Burkina Faso has had two military coups since 2022 and is losing territory to jihadist groups at an alarming rate. The junta expelled French forces, invited Russian Wagner mercenaries, and left ECOWAS.", reasons:["Jihadist groups (JNIM) controlling 40%+ of national territory","Two military coups in 2022","French forces expelled, Russian Wagner mercenaries invited","Withdrawal from ECOWAS","Over 2 million internally displaced"] },
  "858":{ name:"Uruguay", level:1, summary:"Uruguay is consistently ranked as South America's most democratic and peaceful country, with strong institutions, low corruption, and high human development.", reasons:["Occasional fiscal tensions around pension reform","Drug transit activity from neighboring countries"] },
  "860":{ name:"Uzbekistan", level:2, summary:"Uzbekistan under President Mirziyoyev has undertaken significant economic and social reforms, opening the economy and reducing some repression. However, it remains an authoritarian state.", reasons:["Authoritarian single-party governance","2022 Karakalpakstan autonomy protests suppressed violently","Balancing Russia, China, and Western economic interests"] },
  "862":{ name:"Venezuela", level:5, summary:"On January 3, 2026, US forces captured Nicolás Maduro in Caracas. Vice President Delcy Rodríguez was sworn in as Acting President on January 5 after Venezuela's Supreme Court and military endorsed her. The US lifted sanctions on Rodríguez on April 2, 2026 and authorised PDVSA to sell Venezuelan oil directly to US companies — a major diplomatic shift signalling growing US-Rodríguez alignment. In March 2026, Rodríguez replaced longtime Maduro-era loyalist Vladimir Padrino López as defence minister with General Gustavo González López, a significant consolidation move within the military leadership. Venezuela's political order remains fragile.", reasons:["Maduro captured by US military operation (Jan 3, 2026) — unprecedented forced removal","US lifted sanctions on Rodríguez (April 2, 2026) — diplomatic thaw; PDVSA authorised to sell oil to US companies","March 2026: Rodríguez replaced longtime Maduro-era defence minister Padrino López with Gen. Gustavo González López — consolidating military loyalty","Trump declared intent to 'run Venezuela' and grant US oil company access","Edmundo González's US recognition weakening as Washington warms to Rodríguez","Military backing of Rodríguez is fragile; PSUV fracturing","Humanitarian catastrophe continues: 7+ million Venezuelans displaced abroad"] },
  "887":{ name:"Yemen", level:4, summary:"Yemen remains deeply fractured. The Houthis (Ansar Allah) control most of northern Yemen and continued Red Sea shipping attacks well into 2025 despite US/UK retaliatory strikes. A Saudi-Houthi dialogue is ongoing, exploring a political settlement that would entrench Houthi control of the north. The humanitarian crisis remains catastrophic.", reasons:["Houthi Red Sea attacks continuing — global shipping significantly disrupted","US/UK military strikes on Houthi infrastructure escalating regional risk","Saudi-Houthi political dialogue raising prospect of Houthi legitimisation","Yemen's Internationally Recognized Government weakening politically","Catastrophic humanitarian crisis: 21+ million needing aid","Iran continues supplying advanced ballistic missiles and drones to Houthis"] },
  "894":{ name:"Zambia", level:2, summary:"Zambia achieved a peaceful democratic transition in 2021 but is navigating a severe debt crisis requiring restructuring.", reasons:["Debt restructuring and IMF austerity measures","Youth unemployment and poverty","Political polarization between UPND and opposition PF"] },
  "40":  { name:"Austria", level:2, summary:"Austria's September 2024 elections gave the FPÖ the most votes, but coalition talks with Kickl collapsed. The ÖVP's Christian Stocker formed a three-party coalition (ÖVP–SPÖ–Neos) sworn in on March 3, 2025 — Austria's first tripartite coalition since 1949. FPÖ under Kickl sits in opposition with growing support (~35% in polls). The centrist coalition must manage migration pressures, rising defence commitments, and an assertive FPÖ opposition.", reasons:["FPÖ under Kickl polling ~35% and in vocal opposition — government stability under pressure","Three-party coalition (ÖVP–SPÖ–Neos) managing competing centrist priorities","Migration and asylum policy remains the dominant fault line driving FPÖ support","Fiscal constraints limiting defence spending increases demanded by NATO","Balancing EU unity on Ukraine sanctions against domestic Eurosceptic pressures"] },
  "48":  { name:"Bahrain", level:4, summary:"Bahrain has been in a prolonged state of political repression since violently crushing the 2011 Arab Spring uprising. The Shia majority population remains politically marginalized under the Sunni Al-Khalifa monarchy, with thousands of political prisoners and civil society effectively eliminated. On June 9, 2026, Iran launched retaliatory strikes on US military bases on Bahraini soil — the first Iranian attack on Bahrain — dramatically escalating the country's exposure to the US-Iran war. On June 11, Bahrain again activated air defenses against additional Iranian missile strikes following renewed US strikes on Iran.", reasons:["Iran struck US military bases in Bahrain (June 9, 2026) — first Iranian attack on Bahraini soil; direct exposure to US-Iran war","June 11, 2026: Bahrain activated air defenses against additional Iranian missile strikes following renewed US strikes on Iran","Systematic repression of Shia majority population","Thousands of political prisoners post-2011 uprising","Civil society and opposition outlawed","Total dependence on Saudi Arabia for political survival","Regional Iran-Saudi proxy dynamics"] },
  "51":  { name:"Armenia", level:3, summary:"Armenia lost Nagorno-Karabakh to Azerbaijan in September 2023, triggering the displacement of 100,000+ ethnic Armenians. The country is reorienting geopolitically toward the EU, withdrawing from CSTO, and negotiating a peace treaty with Azerbaijan while managing internal political tensions.", reasons:["Loss of Nagorno-Karabakh — 100,000+ Armenian refugees from enclave","Negotiating peace treaty with Azerbaijan under international pressure","Withdrawal from CSTO — security vacuum while Russian protection ends","PM Pashinyan facing domestic opposition over Karabakh loss","Unresolved border demarcation creating ongoing risk of incidents"] },
  "72":  { name:"Botswana", level:1, summary:"Botswana achieved a landmark peaceful democratic transition in 2024, with the ruling BDP losing power for the first time in 58 years. New President Duma Boko has pledged anti-corruption reforms. Botswana remains one of Africa's most stable and well-governed democracies.", reasons:["Declining diamond revenues raising long-term fiscal challenges","Youth unemployment despite relative prosperity","Political transition bringing new governance dynamics"] },
  "96":  { name:"Brunei", level:2, summary:"Brunei is an absolute monarchy with Sharia law partially applied. Political parties are effectively banned. The country is wealthy from oil but faces long-term questions about economic diversification.", reasons:["Absolute monarchy with no political pluralism","Sharia criminal code provisions including flogging and death penalty for homosexuality","Oil dependency and long-term economic diversification challenges"] },
  "108": { name:"Burundi", level:4, summary:"Burundi remains one of Africa's most repressive and impoverished states. The ruling CNDD-FDD party maintains power through violence and intimidation. Over 400,000 refugees remain abroad following the 2015 crisis.", reasons:["Authoritarian CNDD-FDD rule with systematic repression","Ongoing Imbonerakure youth militia violence","Hundreds of thousands of refugees unable to return","Extreme poverty — one of world's poorest nations","Regional tensions with Rwanda"] },
  "148": { name:"Chad", level:4, summary:"Chad's transitional leader Mahamat Idriss Déby, who took power in a coup after his father's death in 2021, won a dubious 2024 presidential election. Sahel instability, armed groups on multiple borders, and the expulsion of French forces make Chad highly vulnerable.", reasons:["Military-transitional government — Déby clan perpetuating dynastic rule","Sahel jihadist spillover from Sudan, CAR, Niger, and Nigeria","2024 expulsion of French forces removed key security guarantor","Sudan civil war creating enormous refugee influx (1 million+)","Extreme poverty and one of lowest HDI scores globally"] },
  "196": { name:"Cyprus", level:3, summary:"Cyprus remains divided since Turkey's 1974 invasion, with the northern third administered as the Turkish Republic of Northern Cyprus (recognised only by Turkey). Reunification negotiations remain stalled. Gas discoveries in Cypriot waters have created new tensions with Turkey.", reasons:["Island partition unresolved — Turkish military occupation of north","Turkish provocations over Cypriot EEZ gas exploration rights","Reunification talks stalled with no credible pathway","EU member but unable to apply EU law in northern territory"] },
  "203": { name:"Czech Republic", level:2, summary:"Czech Republic's Ukraine support stance became uncertain after populist billionaire Andrej Babiš (ANO) was sworn in as PM on December 9, 2025, heading a coalition that includes the pro-Russia Freedom and Direct Democracy (SPD) party. While NATO and EU membership remain intact, the new government is more ambivalent toward Ukraine aid than the previous Fiala administration. President Petr Pavel — a strong Ukraine supporter — provides an institutional counterweight but cannot override the executive.", reasons:["Babiš government (from Dec 2025) includes SPD (explicitly pro-Russia party) — Ukraine arms/financial support uncertain","Coalition partner SPD has called for halt to Ukraine aid and normalisation with Russia","Ukraine war on direct regional doorstep — security concern regardless of government stance","EU rule-of-law concerns emerging under new populist coalition","Minority Roma community facing discrimination"] },
  "204": { name:"Benin", level:2, summary:"Benin held a presidential election on April 12, 2026; Romuald Wadagni, outgoing President Talon's Finance Minister and political protégé, won the presidency. He represents continuity with the Talon government's approach, meaning concerns about democratic backsliding — including opposition exclusion — persist. The jihadist spillover from Burkina Faso into northern Benin remains a growing security threat.", reasons:["Jihadist groups expanding from Burkina Faso into northern Benin","Democratic backsliding continues under Talon-aligned Wadagni government — opposition exclusion ongoing","Tourism and economic pressure from regional instability"] },
  "214": { name:"Dominican Republic", level:2, summary:"The Dominican Republic is a relatively stable Caribbean democracy. President Abinader won re-election in 2024. Tensions with Haiti over migration and the Haitian crisis next door are major concerns, as is deep inequality.", reasons:["Haitian political collapse creating massive migration pressure","Deep inequality and poverty despite economic growth","Corruption and informal economy challenges","Drug trafficking transit routes"] },
  "222": { name:"El Salvador", level:2, summary:"El Salvador under President Bukele (re-elected in 2024) has achieved a dramatic security transformation through mass gang crackdowns. Homicides have fallen by 80%+. However, concerns about authoritarian consolidation, human rights of detainees, and economic sustainability persist.", reasons:["Authoritarian governance — independent institutions weakened","Mass incarceration raising due process concerns","Economic dependency on remittances and vulnerability to US policy","Bitcoin legal tender experiment creating IMF friction"] },
  "233": { name:"Estonia", level:2, summary:"Estonia, a NATO and EU frontline state bordering Russia, faces significant hybrid warfare threats. Russia has used Estonia as a target for cyberattacks, disinformation, and border provocations. The country has significantly increased defence spending and is one of Ukraine's strongest supporters.", reasons:["Direct border with Russia and threat of hybrid warfare","Cyberattack and disinformation campaigns from Russia","Large Russian-speaking minority requiring integration effort","High defence spending strain on public finances"] },
  "242": { name:"Fiji", level:2, summary:"Fiji returned to civilian democratic rule after 2022 elections ended military leader Bainimarama's long dominance. The new coalition government faces economic and climate change challenges.", reasons:["Climate change — sea level rise an existential threat","Recent history of coups and fragile democratic consolidation","Economic vulnerability and high debt","Great-power competition between US, China, and Australia for Pacific influence"] },
  "266": { name:"Gabon", level:3, summary:"Gabon experienced a military coup in August 2023 that ousted President Ali Bongo Ondimba after disputed elections. The military junta led by Brice Oligui Nguema has pledged a transition to civilian rule.", reasons:["Military coup August 2023 — junta running transitional government","Uncertain timeline for return to civilian rule","Oil wealth inequality — elite enrichment vs. widespread poverty","Spillover of Sahel instability and regional coup contagion"] },
  "270": { name:"Gambia", level:2, summary:"Gambia has been undergoing a democratic transition since the peaceful removal of long-time dictator Yahya Jammeh in 2017. The country faces challenges in accountability for past abuses and economic development.", reasons:["Accountability for Jammeh-era human rights abuses — slow justice process","Economic vulnerability and high emigration","Fragile democratic institutions under Barrow","Dependence on tourism and remittances"] },
  "328": { name:"Guyana", level:2, summary:"Guyana is experiencing one of the world's fastest economic transformations due to massive offshore oil discoveries. Oil production has made it the world's fastest-growing economy, but governance capacity, inequality, and ethnic tensions between Afro-Guyanese and Indo-Guyanese communities remain challenges.", reasons:["Oil wealth governance challenges — Dutch disease risk","Ethnic political divisions between major communities","Territorial dispute with Venezuela over Essequibo region (two-thirds of country)","Rapid development pace straining institutional capacity"] },
  "352": { name:"Iceland", level:1, summary:"Iceland is one of the world's most stable and peaceful democracies with no standing army. It manages NATO membership without hosting permanent foreign military forces. Volcanic activity is a recurring natural risk but managed effectively.", reasons:["Frequent volcanic eruptions (Reykjanes Peninsula ongoing activity)","Fishing rights disputes with UK and EU","High cost of living and housing pressure"] },
  "372": { name:"Ireland", level:1, summary:"Ireland is a stable EU democracy experiencing rapid economic growth driven by US multinational investment. Domestic tensions around housing affordability, immigration, and the island's political future (Northern Ireland) are the main concerns.", reasons:["Housing and cost-of-living crisis","Immigration pressure and integration tensions","Northern Ireland constitutional future and Good Friday Agreement integrity","Global minimum tax reform reducing corporate tax advantage"] },
  "388": { name:"Jamaica", level:2, summary:"Jamaica faces a severe gang violence problem concentrated in parts of Kingston, fuelled by the legacy of garrison politics and drug trafficking.", reasons:["Gang violence and organized crime in urban areas","Drug trafficking and extradition dynamics with US","High unemployment among youth","Police brutality concerns and human rights issues"] },
  "426": { name:"Lesotho", level:3, summary:"Lesotho is one of Africa's most politically unstable small states, with multiple coups and political crises in recent decades. The landlocked mountain kingdom is entirely surrounded by South Africa and highly dependent on it economically.", reasons:["History of coups and political instability","Military interference in civilian politics","High HIV/AIDS prevalence — highest in world outside eSwatini","Complete economic dependency on South Africa","High unemployment and poverty"] },
  "428": { name:"Latvia", level:2, summary:"Latvia, a NATO and EU member bordering Russia and Belarus, faces significant security pressure and hybrid warfare threats. On May 14, 2026, PM Evika Siliņa resigned following a political crisis caused by Ukrainian drones crashing on Latvian territory — a stark demonstration that NATO allies are not insulated from Ukraine war spillover. President Rinkēvičs nominated opposition United List leader Andris Kulbergs on May 16, 2026; the Saeima approved Kulbergs's four-party coalition (United List, National Alliance, New Unity, Union of Greens and Farmers) on May 28, 2026 by a 66–25 vote. The new government has a four-month mandate until the October 3, 2026 Saeima elections. The country has substantially increased defence spending, expelled Russian diplomats, and hosts NATO forces on its territory.", reasons:["PM Siliņa resigned May 14, 2026 after Ukrainian drones crashed on Latvian soil; Kulbergs (United List) confirmed as PM by Saeima on May 28 (66–25 vote) — political instability triggered directly by Ukraine war spillover","Direct border with Russia and Belarus — frontline NATO state","Russian-speaking minority (25%) — integration and potential influence vector","Significant Russian hybrid warfare and disinformation campaigns","Defence spending raised to 3%+ of GDP","Baltic energy independence from Russian grid completed 2025"] },
  "440": { name:"Lithuania", level:2, summary:"Lithuania, the first former Soviet state to break free and one of Russia's most vocal critics, has dramatically raised defence spending. It hosts NATO's Enhanced Forward Presence and completed the Baltic electricity grid desynchronisation from Russia in early 2025.", reasons:["Frontline NATO state bordering Russia's Kaliningrad and Belarus","Suwalki Gap — most vulnerable land corridor in NATO","Russia-linked hybrid attacks on infrastructure","Desynchronised electricity grid from Russian BRELL system (completed 2025)","Support for Belarus opposition and Lukashenko pressure"] },
  "442": { name:"Luxembourg", level:1, summary:"Luxembourg is one of the EU's wealthiest and most stable states. As host to major EU institutions and a global financial centre, it faces no domestic security concerns but is deeply integrated in EU geopolitical dynamics.", reasons:["Financial secrecy debates and global minimum tax impact","High cost of living and housing pressure","Dependence on cross-border workers from neighbouring countries"] },
  "450": { name:"Madagascar", level:3, summary:"Madagascar is one of the world's poorest countries with endemic political instability. A disputed 2023 election reinforced Rajoelina's presidency but opposition contests its legitimacy. Climate shocks, food insecurity, and armed banditry in the south are persistent threats.", reasons:["Endemic political instability and disputed elections","Extreme poverty — 80%+ below poverty line","Climate-driven food insecurity in the south","Armed banditry (dahalo) in southern regions","Near-total deforestation creating environmental crisis"] },
  "454": { name:"Malawi", level:2, summary:"Malawi is a poor but relatively stable democracy. Economic challenges including high debt and vulnerability to floods are the main concerns.", reasons:["Extreme poverty — one of world's poorest economies","High public debt and aid dependency","Cyclone and flood vulnerability","Corruption affecting development outcomes"] },
  "458": { name:"Malaysia", level:2, summary:"Malaysia under PM Anwar Ibrahim has maintained political stability after years of government turnover. Religious conservatism and ethnic Malay-Chinese-Indian relations remain underlying tensions, alongside assertive engagement with South China Sea dynamics.", reasons:["Ethnic and religious political tensions between Malay, Chinese, and Indian communities","South China Sea: China's assertive claims overlap with Malaysian continental shelf","LGBTQ+ discrimination under Islamic law in states","Political coalition fragility — razor-thin majorities"] },
  "462": { name:"Maldives", level:2, summary:"The Maldives elected President Muizzu in 2023 on an 'India Out' platform, pivoting toward China. India was asked to withdraw its military personnel. The country faces existential risks from sea-level rise.", reasons:["Geopolitical pivot from India to China creating regional tension","India-Maldives relationship deteriorating","Existential climate threat — islands average 1.5m above sea level","High debt from Chinese infrastructure loans","Political polarization between pro-India and pro-China factions"] },
  "470": { name:"Malta", level:1, summary:"Malta is a small EU island state with stable democratic governance. Its main concerns are irregular migration from North Africa and questions about its historically corruptible justice system.", reasons:["Irregular migration pressure as frontline EU state","Historical concerns about rule of law and corruption","Energy dependency — no land connections to EU grid"] },
  "478": { name:"Mauritania", level:2, summary:"Mauritania has been relatively stable under President Ghazouani. Slavery — though officially abolished — persists in practice, and the country is surrounded by the Sahel's jihadist crisis. New offshore gas revenues (Grande Tortue/Ahmeyim) are beginning to flow.", reasons:["Persistent de facto slavery of Haratin community","Jihadist threat from Mali border (JNIM)","Ethnic tensions between Arab/Berber Beidane and Black African communities","Political transition from strongman rule still consolidating"] },
  "480": { name:"Mauritius", level:1, summary:"Mauritius is one of Africa's most stable and prosperous democracies. The 2024 elections brought a change of government. The main external challenge is a sovereignty dispute with the UK over the Chagos Islands.", reasons:["Chagos Islands / British Indian Ocean Territory sovereignty dispute","Offshore financial centre facing international scrutiny","Climate change vulnerability as a small island state"] },
  "498": { name:"Moldova", level:3, summary:"Moldova is in a precarious security position. Russia's war in Ukraine surrounds it on three sides. The breakaway Transnistria region hosts Russian troops and cut gas supplies in January 2025. Pro-EU President Maia Sandu was re-elected in 2024.", reasons:["Transnistria — Russian-backed breakaway region with Russian troops","Gas cut off from Transnistria's Russian-supplied power plant (Jan 2025)","Direct security threat from Russia-Ukraine war on borders","Pro-EU vs. pro-Russia political polarization","Poverty and emigration reducing domestic political stability"] },
  "499": { name:"Montenegro", level:2, summary:"Montenegro has joined NATO (2017) and is an EU candidate. Internal politics are turbulent with frequent government changes. Serbian Orthodox Church-state tensions and pro-Serbia factions create instability.", reasons:["Frequent government changes and political fragility","Pro-Serbia and pro-Russia factions opposing NATO and EU path","Serbian Orthodox Church property disputes","Organised crime links to political parties","EU accession process demanding difficult reforms"] },
  "554": { name:"New Zealand", level:1, summary:"New Zealand is a stable Pacific democracy with strong institutions. The National-led coalition government is pursuing fiscal consolidation. Treaty of Waitangi Māori rights debates and Pacific security architecture are ongoing discussions.", reasons:["Māori treaty rights and co-governance debates","Gang violence increasing in some communities","Economic housing and cost-of-living pressures","AUKUS/Pacific security — pressure to deepen US defence ties"] },
  "578": { name:"Norway", level:1, summary:"Norway is one of the world's most stable and prosperous countries. Its main security concern is Russia's aggressive posture in the Arctic and cyber/hybrid operations. Norway has dramatically increased defence investment and is a critical gas supplier to Europe.", reasons:["Russia-Norway Arctic tensions — Svalbard territorial friction","Cyber and hybrid warfare threats from Russia","Large sovereign wealth fund creating governance responsibility","Immigration and integration policy debates"] },
  "598": { name:"Papua New Guinea", level:3, summary:"Papua New Guinea faces significant internal security challenges including tribal conflicts, gang violence in Port Moresby, and weak state capacity across its vast and remote territory. A China-US competition for influence over PNG's strategic location and resources is intensifying.", reasons:["Tribal and communal violence in Highlands region","Severe gang crime in Port Moresby","Weak state capacity — vast ungoverned territory","US-China competition for strategic Pacific influence","Secessionist sentiment in Bougainville — independence referendum process"] },
  "600": { name:"Paraguay", level:2, summary:"Paraguay is politically dominated by the Colorado Party, which has held power for most of the last 70 years. Corruption, drug trafficking through its porous borders, and land inequality are the main concerns.", reasons:["Colorado Party dominance limiting political competition","Drug trafficking — Paraguay is major cannabis producer","High inequality in land ownership","Corruption embedded in state institutions","Illicit arms trade affecting neighbours"] },
  "620": { name:"Portugal", level:1, summary:"Portugal has entered a cohabitation phase after Socialist António José Seguro won the presidential election in February 2026 (66.2% vs. Chega's Ventura in the runoff), pairing him with centre-right PM Luís Montenegro's AD government. Seguro's strong mandate sharply reduced Chega's presidential ambitions. Portugal remains stable, but cohabitation creates potential for institutional friction.", reasons:["Cohabitation: Socialist president Seguro vs. centre-right PM Montenegro — potential policy tensions","Far-right Chega defeated at presidential level but remains significant parliamentary force","Housing affordability crisis from tourism and foreign investment","Drought and wildfire vulnerability from climate change","Brain drain — emigration of young educated Portuguese"] },
  "624": { name:"Guinea-Bissau", level:3, summary:"Guinea-Bissau is one of the world's most fragile states, with a history of nine coups or coup attempts since independence in 1974. It remains a major narco-trafficking hub for South American cocaine transiting to Europe.", reasons:["Pervasive narco-trafficking — major transit hub for South American cocaine","History of coups — highly unpredictable political environment","Near-total state institution weakness","Extreme poverty — one of world's lowest HDI rankings","Regional Sahel instability nearby"] },
  "626": { name:"Timor-Leste", level:2, summary:"Timor-Leste is a young democracy that has consolidated peace after independence in 2002. It faces governance challenges and economic reliance on declining oil revenues.", reasons:["Declining oil revenues threatening fiscal sustainability","Youth unemployment and poverty","Occasional political tensions and gang activity","Building state capacity in one of Asia's newest nations"] },
  "642": { name:"Romania", level:2, summary:"Romania's 2024 presidential election was annulled by the Constitutional Court after the first-round surprise victory by far-right, pro-Russian Călin Georgescu (linked to TikTok influence operations). Nicușor Dan won re-run elections in 2025. The episode exposed deep political polarisation and foreign interference vulnerabilities.", reasons:["2024 election crisis — annulled over Russian interference allegations","Far-right and pro-Russia political forces surging","NATO frontline state hosting significant allied forces and F-16s","High fiscal deficit requiring EU-mandated consolidation","Corruption and rule of law concerns"] },
  "694": { name:"Sierra Leone", level:2, summary:"Sierra Leone has maintained post-civil war stability since 2002. The government of President Bio narrowly retained power in disputed 2023 elections. Poverty, youth unemployment, and weak institutions remain the key risk factors.", reasons:["Disputed 2023 election results creating political tension","Extreme poverty and youth unemployment","Weak judicial and security institutions","Historical legacy of civil war trauma"] },
  "703": { name:"Slovakia", level:3, summary:"Prime Minister Robert Fico's government has fundamentally shifted Slovakia's foreign policy. Fico visited Moscow, opposed Ukraine aid, and aligned with Hungary's pro-Russia bloc within the EU. His government has survived significant domestic opposition.", reasons:["Fico's pro-Russia stance — visited Putin, opposed Ukraine weapons","January 2025: threatened to cut electricity to Ukraine over transit dispute","EU rule-of-law concerns — press freedom deteriorating","Fico survived an assassination attempt in May 2024","Deep polarization between pro-EU and pro-Russia factions"] },
  "704": { name:"Vietnam", level:2, summary:"Vietnam under General Secretary Tô Lâm is navigating a delicate balance between US and China. South China Sea tensions with China continue despite close economic ties. Vietnam has signed a comprehensive strategic partnership with the US while maintaining its 'bamboo diplomacy' multi-alignment.", reasons:["South China Sea: China's continuing assertiveness over Vietnamese claims","Political transition — Tô Lâm consolidating power in 2024-25","Balancing US, China, and Russia relationships simultaneously","Press freedom — journalists and bloggers imprisoned","Economic vulnerability to US tariffs under Trump"] },
  "705": { name:"Slovenia", level:1, summary:"Slovenia is a stable NATO and EU member with a high standard of living. PM Robert Golob's liberal government is engaged in EU climate and rule-of-law debates.", reasons:["Housing affordability and cost-of-living tensions","Occasional migration pressure at Croatian-Slovenian border","Energy transition challenges"] },
  "710": { name:"South Africa", level:2, summary:"South Africa's 2024 election produced a landmark result: the ANC lost its outright majority for the first time since 1994, forming a Government of National Unity with the DA and other parties. Load-shedding has significantly improved. Crime, unemployment (33%), and inequality are the dominant domestic challenges. US relations have deteriorated sharply: President Trump barred South Africa from the 2026 G20 Miami summit — the first exclusion of a member in the bloc's 20-year history — and suspended US aid, citing disputed claims of Afrikaner persecution that Pretoria rejects as baseless; South Africa has skipped subsequent G20 sherpa meetings in protest.", reasons:["US-South Africa diplomatic rupture: barred from the 2026 G20 Miami summit (first such exclusion in the bloc's history) and US aid suspended over disputed Afrikaner persecution claims","High unemployment (33%) and extreme inequality — among world's highest Gini coefficients","Crime — among world's highest murder rates","Water infrastructure crisis in major cities","Political tensions within the Government of National Unity coalition","Land reform debates unresolved"] },
  "748": { name:"eSwatini", level:3, summary:"eSwatini (formerly Swaziland) is the last absolute monarchy in Africa. King Mswati III has banned political parties and rules by royal decree. Pro-democracy protests in 2021 were violently suppressed with dozens killed.", reasons:["Absolute monarchy — political parties banned","2021 pro-democracy protests violently suppressed","Arbitrary detention and torture by security forces","Extreme poverty and HIV/AIDS crisis","Economic dependency on South Africa (97% of imports transit through SA)"] },
  "752": { name:"Sweden", level:1, summary:"Sweden joined NATO in March 2024, completing its historic security realignment after 200 years of neutrality. The Tidö coalition government has toughened crime and immigration policy amid a wave of gang shootings. Russia is increasing hybrid warfare pressure.", reasons:["Gang violence — one of Europe's highest per-capita gun homicide rates","Russian hybrid warfare — GPS jamming, disinformation","New NATO member learning alliance dynamics","Immigration and integration policy tensions","Defence spending ramping up significantly"] },
  "768": { name:"Togo", level:3, summary:"Togo's ruling Gnassingbé dynasty has been in power since 1967. The April 2024 elections were followed by a constitutional change shifting to a parliamentary system — widely seen as a manoeuvre to allow President Gnassingbé to remain in power. Jihadist spillover from Burkina Faso threatens the north.", reasons:["Gnassingbé family in power since 1967 — longest-running dynastic rule in Africa","2024 constitutional change to extend power — opposition protests","Jihadist attacks expanding from Burkina Faso into northern Togo","Suppression of political opposition and civil society","Poverty and inequality despite modest growth"] },
  "780": { name:"Trinidad & Tobago", level:2, summary:"Trinidad & Tobago faces a serious gang violence and murder problem, with one of the world's highest per-capita murder rates. Drug trafficking through the twin-island state from South America is a systemic challenge. Declining oil and gas revenues are squeezing the government's fiscal position.", reasons:["Among world's highest murder rates per capita","Drug trafficking and gang activity","Declining hydrocarbon revenues reducing fiscal space","Venezuelan refugee influx creating social tension"] },
  "795": { name:"Turkmenistan", level:3, summary:"Turkmenistan under President Serdar Berdimuhamedow is one of the world's most repressive and isolated states. It controls the world's fourth-largest natural gas reserves but the population faces severe poverty.", reasons:["Among world's most repressive regimes — total press suppression","Personality cult — successor dynasty to Niyazov","Population facing poverty despite gas wealth","No civil society, elections, or political competition","Closed economy with near-zero foreign engagement"] },
  "834": { name:"Tanzania", level:2, summary:"Tanzania under President Samia Suluhu Hassan has shown a more open political environment than her predecessor. However, opposition is still restricted and Zanzibar has periodic separatist tensions. Tanzania hosts one of Africa's largest refugee populations from Burundi and DRC.", reasons:["Restrictions on political opposition and press freedom","Zanzibar semi-autonomy tensions and occasional unrest","Hosting large refugee populations from Burundi and DRC","Tanzanian military engagement in DRC via SADC mission","Environmental pressure on Serengeti from development corridors"] }
};
